# ─── رتبه‌بندی ───
 
def _rank_users(data: dict, key: str) -> list:
    entries = []
    for uid, ud in data.get("users", {}).items():
        entries.append({"uid": uid, "name": ud.get("name") or f"#{uid[-4:]}",
                        "score": ud.get(key, 0), "coins": ud.get("coins", 0)})
    entries.sort(key=lambda x: (-x["score"], -x["coins"]))
    for i, e in enumerate(entries):
        if i == 0:
            e["rank"] = 1
        else:
            prev = entries[i - 1]
            e["rank"] = prev["rank"] if (e["score"] == prev["score"] and e["coins"] == prev["coins"]) else i + 1
    return entries
 
def _get_ranking(key: str, user_id: int):
    data = load_leaderboard()
    ranked = _rank_users(data, key)
    top3 = [e for e in ranked if e["rank"] <= 3][:3]
    user_rank = next((e["rank"] for e in ranked if e["uid"] == str(user_id)), None)
    return top3, user_rank
 
# ─── ساخت متن لیدربورد ───
 
_MEDALS = {1: "🥇", 2: "🥈", 3: "🥉"}

def _build_lb_text(title, subtitle, top3, user_rank, key, lang="fa") -> str:
    t = _T(lang)
    lines = [
        f"🏆 *{title}*",
        "",
        f"_{subtitle}_",
        "",
    ]
    if not top3 or all(e["score"] == 0 for e in top3):
        lines += [t("lb_no_score")]
    else:
        for e in top3:
            medal = _MEDALS.get(e["rank"], "🏅")
            if key == "weekly_purchase_toman":
                score_text = f"{int(e['score']):,} {t('lb_unit_toman')}"
            elif key == "weekly_joins":
                score_text = f"{int(e['score'])} {t('lb_unit_channel')}"
            else:
                score_text = f"{int(e['score'])} {t('lb_unit_person')}"
            lines.append(f"{medal} *{e['name']}*  —  {score_text}")
    lines.append("")
    if user_rank:
        lines.append(t("lb_your_rank").format(rank=user_rank))
    else:
        lines.append(t("lb_no_rank"))
    lines += ["", t("lb_prizes_note")]
    return "\n".join(lines)


def build_member_leaderboard_text(user_id: int, lang="fa") -> str:
    t = _T(lang)
    top3, user_rank = _get_ranking("weekly_joins", user_id)
    return _build_lb_text(t("lb_member_title"), t("lb_member_sub"), top3, user_rank, "weekly_joins", lang)


def build_referral_leaderboard_text(user_id: int, lang="fa") -> str:
    t = _T(lang)
    top3, user_rank = _get_ranking("weekly_referrals", user_id)
    return _build_lb_text(t("lb_referral_title"), t("lb_referral_sub"), top3, user_rank, "weekly_referrals", lang)


def build_purchase_leaderboard_text(user_id: int, lang="fa") -> str:
    t = _T(lang)
    top3, user_rank = _get_ranking("weekly_purchase_toman", user_id)
    return _build_lb_text(t("lb_purchase_title"), t("lb_purchase_sub"), top3, user_rank, "weekly_purchase_toman", lang)
# ─── توزیع جوایز هفتگی ───
 
def _distribute_prizes_for_category(ranked: list, key: str, category_key: str):
    users_data = load_users()
    winners = [e for e in ranked if e["rank"] <= 3 and e["score"] > 0]
    prizes = {1: LEADERBOARD_PRIZE_1ST, 2: LEADERBOARD_PRIZE_2ND, 3: LEADERBOARD_PRIZE_3RD}
    for w in winners:
        prize = prizes.get(w["rank"], 0)
        if not prize:
            continue
        uid = w["uid"]
        if uid in users_data:
            users_data[uid]["coins"] = users_data[uid].get("coins", 0) + prize
        winner_lang = users_data.get(uid, {}).get("lang", "fa")
        wt = _T(winner_lang)
        if key == "weekly_purchase_toman":
            score_str = wt("score_unit_toman").format(value=f"{int(w['score']):,}")
        elif key == "weekly_joins":
            score_str = wt("score_unit_channel").format(value=int(w['score']))
        else:
            score_str = wt("score_unit_person").format(value=int(w['score']))
        category_label = wt(category_key)
        msg = wt("prize_win_msg").format(
            category=category_label, rank=w["rank"], prize=prize, score=score_str)
        try:
            bale_api.send_message(int(uid), msg)
        except Exception as e:
            print(f"[prize] send to {uid}: {e}")
    save_users(users_data)
 
def distribute_weekly_prizes():
    print("[leaderboard] Distributing weekly prizes...")
    lb_data = load_leaderboard()
    member_ranked   = _rank_users(lb_data, "weekly_joins")
    referral_ranked = _rank_users(lb_data, "weekly_referrals")
    purchase_ranked = _rank_users(lb_data, "weekly_purchase_toman")
    _distribute_prizes_for_category(member_ranked,   "weekly_joins",          "lb_category_member")
    _distribute_prizes_for_category(referral_ranked, "weekly_referrals",      "lb_category_referral")
    _distribute_prizes_for_category(purchase_ranked, "weekly_purchase_toman", "lb_category_purchase")
    for uid in lb_data["users"]:
        lb_data["users"][uid]["weekly_joins"]          = 0
        lb_data["users"][uid]["weekly_referrals"]      = 0
        lb_data["users"][uid]["weekly_purchase_toman"] = 0.0
    lb_data["week_start"]       = datetime.now().isoformat()
    lb_data["last_prize_given"] = datetime.now().isoformat()
    save_leaderboard(lb_data)
    print("[leaderboard] Done. Stats reset.")
 
def _next_friday_midnight() -> float:
    now = datetime.now()
    days_ahead = (4 - now.weekday()) % 7
    if days_ahead == 0:
        target = now.replace(hour=0, minute=0, second=0, microsecond=0)
        if now >= target:
            days_ahead = 7
    next_friday = now + timedelta(days=days_ahead)
    target = next_friday.replace(hour=0, minute=0, second=0, microsecond=0)
    return (target - now).total_seconds()
 
def leaderboard_scheduler():
    """Thread دائمی - هر جمعه ساعت ۱۲ شب جوایز می‌ده"""
    while True:
        wait_seconds = _next_friday_midnight()
        print(f"[leaderboard] Next prize in {wait_seconds/3600:.1f} hours")
        time.sleep(max(wait_seconds, 1))
        try:
            distribute_weekly_prizes()
        except Exception as e:
            print(f"[leaderboard] prize error: {e}")
        time.sleep(60)
 
 
