def is_user_in_channel(user_id):
    try:
        res = bale_api.get_chat_member(CHANNEL_USERNAME, user_id)
        if res and res.get("ok"):
            return res["result"].get("status") in ("member", "administrator", "creator")
    except Exception as e:
        print(f"[membership] {e}")
    return False
 
# کش chat_id عددی کانال‌ها (از config پر می‌شه)
_channel_id_cache = {
    rc["username"].lstrip("@").lower(): rc["chat_id"]
    for rc in REQUIRED_CHANNELS
    if rc.get("chat_id")
}

def _resolve_channel_id(username: str):
    key = username.lstrip("@").lower()
    if key in _channel_id_cache and _channel_id_cache[key]:
        return _channel_id_cache[key]
    try:
        res = bale_api.get_chat(f"@{key}")
        if res and res.get("ok"):
            cid = res["result"].get("id")
            if cid:
                _channel_id_cache[key] = cid
                return cid
    except Exception:
        pass
    return None

def _main_channel_target():
    """chat_id عددی کانال اصلی (اگر کش شده) یا در غیر اینصورت خود username."""
    key = CHANNEL_USERNAME.lstrip("@").lower()
    return _channel_id_cache.get(key) or CHANNEL_USERNAME

def is_user_in_specific_channel(channel_username, user_id):
    ch = channel_username.strip().lstrip("@").lower()

    def _check(cid):
        try:
            res = bale_api.get_chat_member(cid, user_id)
            if not res:
                return None
            if res.get("ok"):
                status = res["result"].get("status", "")
                # member, administrator, creator = عضو
                # left, kicked, restricted = عضو نیست
                if status in ("member", "administrator", "creator"):
                    return True
                if status in ("left", "kicked"):
                    return False
                if status == "restricted":
                    return True
                return False
            # ok=False
            err = res.get("description", "").lower()
            code = res.get("error_code", 0)
            if code == 404 or "no such" in err:
                return None  # نتونست پیدا کنه → با روش دیگه امتحان کن
            if "not a member" in err or "user not found" in err:
                return False
            return None
        except Exception:
            return None

    # اول با chat_id عددی
    numeric_id = _resolve_channel_id(ch)
    if numeric_id:
        result = _check(numeric_id)
        if result is not None:
            return result

    # بعد با @username
    result = _check(f"@{ch}")
    if result is not None:
        return result

    # نتونستیم چک کنیم = False (امن‌تره از True)
    return False
 
def is_bot_admin_in_channel(channel_username):
    try:
        me_res = bale_api.get_me()
        if me_res and me_res.get("ok"):
            bot_id = me_res["result"].get("id")
            if bot_id:
                m = bale_api.get_chat_member(channel_username, bot_id)
                if m and m.get("ok"):
                    return m["result"].get("status") in ("administrator", "creator")
        adm = bale_api.get_chat_administrators(channel_username)
        if adm and adm.get("ok"):
            return any(a.get("user", {}).get("is_bot") for a in adm.get("result", []))
    except Exception as e:
        print(f"[bot_admin] {e}")
    return False
 
def _channel_admin_status(channel_username):
    """
    وضعیت ادمین بودن ربات در یک کانال را برمی‌گرداند:
    'admin'     -> ربات هنوز ادمین کانال است
    'not_admin' -> کانال پیدا شد ولی ربات دیگر ادمین آن نیست (ادمینی خارج شده)
    'not_found' -> کانال اصلاً پیدا نشد (لینک/آیدی کانال عوض شده یا نامعتبر است)
    """
    try:
        chat_res = bale_api.get_chat(channel_username)
    except Exception:
        chat_res = None
    if not chat_res or not chat_res.get("ok"):
        return "not_found"
    try:
        me_res = bale_api.get_me()
        bot_id = me_res["result"].get("id") if me_res and me_res.get("ok") else None
        if bot_id:
            m = bale_api.get_chat_member(channel_username, bot_id)
            if m and m.get("ok"):
                status = m["result"].get("status")
                return "admin" if status in ("administrator", "creator") else "not_admin"
        adm = bale_api.get_chat_administrators(channel_username)
        if adm and adm.get("ok"):
            is_admin = any(a.get("user", {}).get("is_bot") for a in adm.get("result", []))
            return "admin" if is_admin else "not_admin"
    except Exception as e:
        print(f"[channel_admin_status] {e}")
    return "not_admin"


def order_channel_monitor():
    """
    Thread دائمی: سلامت کانال سفارش‌های فعال را با فاصله کوتاه بررسی می‌کند.
    اگر ربات از ادمینی خارج شده یا کانال پیدا نشود، سفارش فوراً لغو و
    سکه باقی‌مانده به صاحب سفارش برگردانده می‌شود.

    بهینه‌سازی‌ها:
    - فاصله بین دورها ~15 ثانیه (به‌جای 180)
    - کانال‌های یکتا فقط یک‌بار چک می‌شوند
    - چک‌های API به‌صورت موازی انجام می‌شوند
    """
    from concurrent.futures import ThreadPoolExecutor, as_completed

    CHECK_INTERVAL = 15          # ثانیه بین هر دور کامل
    MAX_PARALLEL = 8             # حداکثر چک همزمان API

    while True:
        try:
            orders_data = load_orders()
            active_orders = [o for o in orders_data.get("orders", []) if o.get("status") == "active"]
            if not active_orders:
                time.sleep(CHECK_INTERVAL)
                continue

            # کانال‌های یکتا → لیست سفارش‌های مربوط به هر کانال
            channel_to_orders = {}
            for order in active_orders:
                channel_id = order.get("channel_id")
                if not channel_id:
                    continue
                key = str(channel_id).strip().lower()
                channel_to_orders.setdefault(key, {"channel_id": channel_id, "orders": []})
                channel_to_orders[key]["orders"].append(order)

            def _check_one(ch_id):
                try:
                    return ch_id, _channel_admin_status(ch_id)
                except Exception as e:
                    print(f"[order_channel_monitor/check {ch_id}] {e}")
                    return ch_id, None

            statuses = {}
            with ThreadPoolExecutor(max_workers=min(MAX_PARALLEL, max(1, len(channel_to_orders)))) as pool:
                futures = {
                    pool.submit(_check_one, info["channel_id"]): key
                    for key, info in channel_to_orders.items()
                }
                for fut in as_completed(futures):
                    ch_id, status = fut.result()
                    if status is not None:
                        statuses[str(ch_id).strip().lower()] = status

            # اعمال نتیجه روی همه سفارش‌های همان کانال
            for key, info in channel_to_orders.items():
                status = statuses.get(key)
                if status == "not_found":
                    for order in info["orders"]:
                        if order.get("status") == "active":
                            _force_cancel_order(order, orders_data, "order_cancelled_link_changed")
                elif status == "not_admin":
                    for order in info["orders"]:
                        if order.get("status") == "active":
                            _force_cancel_order(order, orders_data, "order_cancelled_bot_removed")
        except Exception as e:
            print(f"[order_channel_monitor] {e}")
        time.sleep(CHECK_INTERVAL)


def get_bot_admin_channels():
    """
    لیست تمام کانال‌هایی که ربات هم‌اکنون در آن‌ها ادمین است، به‌جز ۳ کانال اصلی
    ربات (آرکا ممبر، آرکا آپدیت، آرکا کد). کاندیدها از کانال‌های جوین اجباری
    خریداری‌شده و کانال‌های ثبت‌شده در سفارش‌های ممبر جمع‌آوری می‌شوند و سپس
    ادمین‌بودن واقعی ربات در هرکدام به‌صورت زنده بررسی می‌شود.
    """
    excluded = {ch["username"].lstrip("@").lower() for ch in REQUIRED_CHANNELS}
    candidates = set()
    mj_data = load_mandatory_join()
    for ch in mj_data.get("channels", []):
        uname = ch.get("channel_username", "")
        if uname:
            candidates.add(uname.lstrip("@").lower())
    orders_data = load_orders()
    for order in orders_data.get("orders", []):
        ch = order.get("channel_id")
        if ch:
            candidates.add(str(ch).lstrip("@").lower())
    candidates -= excluded
    result = []
    for uname in candidates:
        full = f"@{uname}"
        if _channel_admin_status(full) == "admin":
            result.append(full)
    return result


