def _get_or_init_user(users, user_id_str):
    if user_id_str not in users:
        users[user_id_str] = {"coins": 10, "rules_accepted": False,
                               "joined_channels": {}, "state": "idle",
                               "has_started": False, "referrals": 0,
                               "wheel_spins": 0, "signup_rewards": {},
                               "lang": get_default_lang(),
                               "joined_at": datetime.now().isoformat(),
                               "last_seen": datetime.now().isoformat()}
    return users[user_id_str]
 
def _max_members_for_coins(coins):
    return int(coins / 2)
 
def _is_vip(user_id_str, users):
    vip_until = users.get(user_id_str, {}).get("vip_until")
    if not vip_until:
        return False
    return datetime.now() < datetime.fromisoformat(vip_until)

def _user_in_all_required_channels(user_id):
    """چک می‌کند که کاربر در همه کانال‌های اجباری عضو است."""
    for ch in _all_required_channels():
        if not is_user_in_specific_channel(ch["username"], user_id):
            return False
    return True
 
def _required_channels_gate(chat_id, user_id):
    """
    گیت سراسری عضویت اجباری. اگر کاربر عضو همه‌ی کانال‌های اجباری
    (ثابت + جوین اجباری خریداری‌شده) نباشد، پیام عضویت را نشان می‌دهد
    و True برمی‌گرداند تا فراخواننده از ادامه‌ی پردازش صرف‌نظر کند.
    اقدامات مخصوص پنل ادمین پیش از رسیدن به این گیت، جدا مدیریت و
    return می‌شوند؛ پس این گیت تأثیری روی خود پنل ادمین ندارد.
    """
    users = load_users()
    u = users.get(str(user_id), {})
    if not u.get("has_started") or not u.get("rules_accepted"):
        return False
    if _user_in_all_required_channels(user_id):
        return False
    lang = u.get("lang", "fa")
    t = _T(lang)
    bale_api.send_message(chat_id, t("join_prompt"),
                          reply_markup=build_keyboard_channel_join_and_check(lang))
    return True


def _get_channel_bio(channel_username):
    try:
        res = bale_api.get_chat(channel_username)
        if res and res.get("ok"):
            return res["result"].get("description", "")
    except Exception as e:
        print(f"[bio] {e}")
    return ""
 
def _get_user_display_name(users, user_id_str):
    """نام نمایشی کاربر برای لیدربورد"""
    u = users.get(user_id_str, {})
    return u.get("first_name") or u.get("name") or f"#{user_id_str[-4:]}"

def _remember_user_profile(users, user_id_str, from_obj=None):
    user = _get_or_init_user(users, user_id_str)
    user["last_seen"] = datetime.now().isoformat()
    if not from_obj:
        return
    first_name = from_obj.get("first_name") or from_obj.get("name")
    username = from_obj.get("username")
    if first_name:
        user["first_name"] = first_name
    if username:
        user["username"] = username

def _referral_link(user_id):
    return f"{BOT_URL}?start=ref_{user_id}"

def _process_referral(new_user_id, payload, users):
    if not payload.startswith("ref_"):
        return
    new_user_id_str = str(new_user_id)
    inviter_id_str = payload[4:].strip()
    if not inviter_id_str.isdigit() or inviter_id_str == new_user_id_str:
        return
    new_user = _get_or_init_user(users, new_user_id_str)
    if new_user.get("has_started") or new_user.get("invited_by"):
        return
    inviter = _get_or_init_user(users, inviter_id_str)
    new_user["invited_by"] = inviter_id_str
    new_user["coins"] = round(new_user.get("coins", 0) + 20, 2)
    inviter["coins"] = round(inviter.get("coins", 0) + 20, 2)
    inviter["referrals"] = inviter.get("referrals", 0) + 1
    inviter["wheel_spins"] = inviter.get("wheel_spins", 0) + 0
    try:
        lb_record_referral(int(inviter_id_str), _get_user_display_name(users, inviter_id_str), inviter["coins"])
    except Exception as e:
        print(f"[referral_lb] {e}")
    try:
        inviter_lang = _get_user_lang(int(inviter_id_str))
        it = _T(inviter_lang)
        bale_api.send_message(int(inviter_id_str),
            it("referral_congrats_msg").format(referrals=inviter['referrals']))
    except Exception as e:
        print(f"[referral_msg] {e}")

def _available_wheel_spins(user):
    earned = int(user.get("referrals", 0)) // 5
    used = int(user.get("wheel_spins_used", 0))
    bonus = int(user.get("bonus_wheel_spins", 0))
    return max(0, earned + bonus - used)

