def delete_gift_code(code):
    data = load_gift_codes()
    code = code.strip().upper()
    if code in data["codes"]:
        del data["codes"][code]
        save_gift_codes(data)
        return True
    return False

def _spin_wheel_result(is_vip):
    if is_vip:
        prizes = [
            ("coins", 20, 8),
            ("coins", 15, 10),
            ("coins", 10, 18),
            ("coins", 5, 22),
            ("code", 5, 14),
            ("vip", 1, 10),
        ]
    else:
        prizes = [
            ("coins", 15, 9),
            ("coins", 10, 16),
            ("coins", 7, 18),
            ("coins", 5, 20),
            ("again", 1, 9),
            ("code", 5, 7),
            ("vip", 1, 5),
        ]
    return random.choices(prizes, weights=[p[2] for p in prizes], k=1)[0]

