def _place_order(chat_id, user_id, user_id_str, member_count, coins_needed):
    users = load_users()
    user_coins = users.get(user_id_str, {}).get("coins", 0)
    lang = users.get(user_id_str, {}).get("lang", "fa")
    t = _T(lang)
    if user_coins < coins_needed:
        bale_api.send_message(
            chat_id,
            INSUFFICIENT_COINS_MESSAGE_TEMPLATE.format(needed=coins_needed, balance=user_coins),
            reply_markup=_build_menu(user_id, lang)
        )
        return
 
    is_user_vip = _is_vip(user_id_str, users)
    orders = load_orders()
    order_id = orders["next_order_id"]
    orders["next_order_id"] += 1
    channel_id = users[user_id_str].get("order_channel", "")
    channel_link = get_channel_invite_link(channel_id)
 
    order = {
        "order_id": order_id, "user_id": user_id, "channel_id": channel_id,
        "channel_link": channel_link, "member_count": member_count,
        "members_joined": 0, "coins_needed": coins_needed,
        "coins_remaining": coins_needed, "status": "active",
        "is_vip": is_user_vip, "message_id": None, "report_count": 0,
        "created_at": datetime.now().strftime("%Y-%m-%d %H:%M")
    }
    orders["orders"].append(order)
    save_orders(orders)

    users[user_id_str]["coins"] = user_coins - coins_needed
    users[user_id_str]["state"] = "idle"
    users[user_id_str].pop("order_channel", None)
    save_users(users)

    if is_user_vip:
        bio = _get_channel_bio(channel_id)
        bio_line = f"{bio}\n\n" if bio else ""
        order_message = f"🎖سفارش《*VIP*》#{order_id}\n\n{bio_line}- [x] {channel_link}"
    else:
        order_message = ORDER_CHANNEL_MESSAGE_TEMPLATE.format(
            order_id=order_id, channel_link=channel_link)

    _ch_target = _main_channel_target()
    channel_msg = bale_api.send_message(
        _ch_target, order_message,
        reply_markup=build_order_channel_inline_keyboard(channel_link, order_id))
    if channel_msg and channel_msg.get("ok"):
        order["message_id"] = channel_msg["result"].get("message_id")
        save_orders(orders)

    bale_api.send_message(
        chat_id,
        t("order_placed").format(order_id=order_id),
        reply_markup=_build_menu(user_id, lang)
    )
 
 
