def handle_start(chat_id, user_id, payload="", from_obj=None):
    users = load_users()
    user_id_str = str(user_id)
    user = _get_or_init_user(users, user_id_str)
    _remember_user_profile(users, user_id_str, from_obj)
    _process_referral(user_id, payload, users)
    first_start = not user.get("has_started")
    user["has_started"] = True
    save_users(users)
 
    if user.get("rules_accepted"):
        lang = user.get("lang", "fa")
        t = _T(lang)
        all_joined = all(
            is_user_in_specific_channel(ch["username"], user_id)
            for ch in _all_required_channels()
        )
        if all_joined:
            if is_admin_user(user_id):
                kb = build_reply_main_menu_admin(lang)
            else:
                kb = build_reply_main_menu(lang)
            bale_api.send_message(chat_id, t("welcome"), reply_markup=kb)
            _send_active_predictions_to_user(user_id, lang)
        else:
            bale_api.send_message(chat_id, t("join_prompt"),
                                  reply_markup=build_keyboard_channel_join_and_check(lang))
    else:
        _rules_lang = user.get("lang", "fa")
        bale_api.send_message(chat_id, RULES_MESSAGES.get(_rules_lang, RULES_MESSAGES["fa"]),
                              reply_markup=build_keyboard_initial_welcome(_rules_lang))

    if payload.startswith("ref_") and first_start and users.get(user_id_str, {}).get("invited_by"):
        _rjb_lang = users.get(user_id_str, {}).get("lang", "fa")
        bale_api.send_message(chat_id,
            _T(_rjb_lang)("referral_join_bonus_msg"))
 
 
