def handle_signup_done(chat_id, user_id, offer_key, from_obj=None):
    lang = _get_user_lang(user_id)
    t = _T(lang)
    users = load_users()
    user_id_str = str(user_id)
    user = _get_or_init_user(users, user_id_str)
    _remember_user_profile(users, user_id_str, from_obj)
    offer = SIGNUP_OFFERS[offer_key]
    title = t(f"offer_title_{offer_key}")
    state = user.setdefault("signup_rewards", {}).get(offer_key, {})
    if state.get("status") == "approved":
        bale_api.send_message(chat_id,
            t("signup_already_approved").format(title=title),
            reply_markup=build_signup_gift_keyboard(lang))
        save_users(users)
        return
    if state.get("status") == "pending":
        bale_api.send_message(chat_id,
            t("signup_already_pending"),
            reply_markup=build_signup_gift_keyboard(lang))
        save_users(users)
        return
    requests = load_signup_requests()
    request_id = requests["next_id"]
    requests["next_id"] += 1
    request = {
        "id": request_id, "user_id": user_id, "offer_key": offer_key,
        "offer_title": offer["title"], "coins": offer["coins"],
        "status": "pending", "created_at": datetime.now().isoformat(),
    }
    requests["requests"].append(request)
    user["signup_rewards"][offer_key] = {"status": "pending", "request_id": request_id}
    save_signup_requests(requests)
    save_users(users)
    username = (from_obj or {}).get("username") or user.get("username") or "-"
    name = (from_obj or {}).get("first_name") or user.get("first_name") or "-"
    now_str = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    bale_api.send_message(chat_id,
        t("signup_request_submitted").format(title=title, coins=offer["coins"]),
        reply_markup=build_signup_gift_keyboard(lang))
    admin_lang = _get_user_lang(ADMIN_ID)
    at = _T(admin_lang)
    admin_text = at("admin_new_signup_request").format(
        request_id=request_id, title=at(f"offer_title_{offer_key}"),
        name=name, user_id=user_id, username=username, date=now_str, coins=offer["coins"])
    bale_api.send_message(ADMIN_ID, admin_text, reply_markup=build_admin_signup_keyboard(request_id, admin_lang))

