def handle_my_orders(chat_id, user_id):
    lang = _get_user_lang(user_id)
    t = _T(lang)
    orders = load_orders()
    service_orders = load_service_orders()
    user_orders = [o for o in orders["orders"] if o["user_id"] == user_id]
    user_svc = [o for o in service_orders["orders"] if o["user_id"] == user_id and o["status"] != "pending_payment"]
    if not user_orders and not user_svc:
        bale_api.send_message(chat_id, t("no_orders_msg"), reply_markup=_build_menu(user_id, lang))
        return
    bale_api.send_message(chat_id, t("orders_list_msg"))
    status_map = {
        "active":    t("status_active"),
        "completed": t("status_completed"),
        "cancelled": t("status_cancelled"),
    }
    for o in user_orders[-5:][::-1]:
        status = status_map.get(o.get("status", ""), o.get("status", ""))
        vip_tag = t("vip_tag") if o.get("is_vip") else t("normal_tag")
        text = t("order_card_template").format(
            order_id=o['order_id'], channel_id=o.get('channel_id', '-'),
            vip_tag=vip_tag, status=status,
            joined=o.get('members_joined', 0), member_count=o.get('member_count', 0),
            coins_needed=o.get('coins_needed', 0),
        )
        if o.get("status") == "active":
            kb = {"inline_keyboard": [[{"text": t("btn_cancel_order"), "callback_data": f"cancel_order:{o['order_id']}"}]]}
            bale_api.send_message(chat_id, text, reply_markup=kb)
        else:
            bale_api.send_message(chat_id, text)
    svc_status_map = {
        "pending": t("status_pending"),
        "approved": status_map["completed"],
        "rejected": status_map["cancelled"],
    }
    for o in user_svc[-5:][::-1]:
        svc_name = _svc_full_name(o.get("service_key", ""), lang)
        status = svc_status_map.get(o.get("status",""), o.get("status",""))
