def handle_transfer_target_input(chat_id, user_id, text):
    lang = _get_user_lang(user_id)
    t = _T(lang)
    users = load_users()
    user_id_str = str(user_id)
    username_input = text.strip().lstrip("@")
    if not username_input:
        bale_api.send_message(chat_id, t("invalid_user_id"), reply_markup=build_back_keyboard(lang))
        return
    target_id = None
    for uid_str, urec in users.items():
        uname = (urec.get("username") or "").lstrip("@")
        if uname and uname.lower() == username_input.lower():
            target_id = int(uid_str)
            break
    if target_id is None:
        bale_api.send_message(chat_id, t("transfer_not_started"), reply_markup=build_back_keyboard(lang))
        return
    if target_id == user_id:
        bale_api.send_message(chat_id, t("transfer_self"), reply_markup=build_back_keyboard(lang))
        return
    users[user_id_str]["transfer_target"] = target_id
    users[user_id_str]["state"] = "waiting_for_transfer_amount"
    save_users(users)
    tax_text = "2%" if _is_vip(user_id_str, users) else "5%"
    bale_api.send_message(chat_id,
        t("transfer_amount_msg").format(tax=tax_text),
        reply_markup=build_back_keyboard(lang))
 
def handle_transfer_amount_input(chat_id, user_id, text):
    lang = _get_user_lang(user_id)
    t = _T(lang)
    users = load_users()
    user_id_str = str(user_id)
    try:
        amount = float(text.strip())
        if amount <= 0:
            raise ValueError
    except ValueError:
        bale_api.send_message(chat_id, t("invalid_number"), reply_markup=build_back_keyboard(lang))
        return
    if amount < get_min_transfer_coins():
        bale_api.send_message(chat_id, t("transfer_min").format(min=_fmt_coins(get_min_transfer_coins())), reply_markup=build_back_keyboard(lang))
        return
    user_coins = users[user_id_str].get("coins", 0)
    tax_rate = 0.02 if _is_vip(user_id_str, users) else 0.05
    tax = round(amount * tax_rate, 2)
    total_deduct = round(amount + tax, 2)
    received = round(amount - tax, 2)
    if user_coins < total_deduct:
        bale_api.send_message(chat_id,
            t("insufficient_transfer").format(needed=total_deduct, balance=user_coins),
            reply_markup=build_back_keyboard(lang))
        return
    target_id = users[user_id_str].get("transfer_target")
    target_id_str = str(target_id)
    users[user_id_str]["coins"] = round(user_coins - total_deduct, 2)
    users[user_id_str]["state"] = "idle"
    users[user_id_str].pop("transfer_target", None)
    target_coins = users[target_id_str].get("coins", 0)
    users[target_id_str]["coins"] = round(target_coins + received, 2)
    save_users(users)
    # ── ذخیره لاگ انتقال ──
    _log_transfer(user_id, target_id, amount, tax, received)
    bale_api.send_message(chat_id,
        t("transfer_done").format(amount=amount, tax=tax),
        reply_markup=_build_menu(user_id, lang))
    t_target = _T(_get_user_lang(target_id))
    sender_username = users.get(user_id_str, {}).get("username")
    sender_label = f"@{sender_username}" if sender_username else str(user_id)
    bale_api.send_message(target_id,
        t_target("transfer_received").format(amount=amount, tax=tax, user_id=sender_label))
 
