def get_disabled_required_channels():
    return load_settings().get("disabled_required_channels", [])

def _disable_required_channel(username):
    data = load_settings()
    lst = data.get("disabled_required_channels", [])
    uname = username.lstrip("@")
    if uname not in lst:
        lst.append(uname)
    data["disabled_required_channels"] = lst
    save_settings(data)

def _enable_required_channel(username):
    data = load_settings()
    lst = data.get("disabled_required_channels", [])
    uname = username.lstrip("@")
    if uname in lst:
        lst.remove(uname)
    data["disabled_required_channels"] = lst
    save_settings(data)

def _all_required_channels():
    """کانال‌های اجباری ثابت (config، منهای موارد حذف‌شده توسط ادمین) + کانال‌های جوین اجباری خریداری‌شده/دستی و هنوز فعال."""
    disabled = set(get_disabled_required_channels())
    base = [ch for ch in REQUIRED_CHANNELS if ch["username"].lstrip("@") not in disabled]
    data = load_mandatory_join()
    dynamic = []
    for ch in data.get("channels", []):
        if ch.get("active"):
            uname = ch["channel_username"]
            dynamic.append({
                "username": uname, "chat_id": None,
                "url": f"https://ble.ir/{uname.lstrip('@')}",
                "label": uname.lstrip("@"),
            })
    return base + dynamic

def add_manual_required_channel(username):
    """ادمین یک کانال را دستی به جوین اجباری اضافه می‌کند (بدون انقضا)."""
    username = username if username.startswith("@") else f"@{username}"
    data = load_mandatory_join()
    for ch in data.get("channels", []):
        if ch.get("active") and ch.get("channel_username", "").lower() == username.lower():
            return False
    for rc in REQUIRED_CHANNELS:
        if rc["username"].lower() == username.lower() and rc["username"].lstrip("@") not in get_disabled_required_channels():
            return False
    new_id = max([c.get("id", 0) for c in data.get("channels", [])], default=0) + 1
    data.setdefault("channels", []).append({
        "id": new_id,
        "channel_username": username,
        "user_id": ADMIN_ID,
        "purchase_id": None,
        "days": None,
        "created_at": datetime.now().isoformat(),
        "expires_at": None,
        "active": True,
        "source": "admin",
    })
    save_mandatory_join(data)
    return True

def remove_required_channel(username):
    """کانال را (چه ثابت، چه خریداری‌شده، چه دستی) از جوین اجباری خارج می‌کند."""
    uname = username.lstrip("@")
    for rc in REQUIRED_CHANNELS:
        if rc["username"].lstrip("@").lower() == uname.lower():
            _disable_required_channel(uname)
            return True
    data = load_mandatory_join()
    changed = False
    for ch in data.get("channels", []):
        if ch.get("active") and ch.get("channel_username", "").lstrip("@").lower() == uname.lower():
            ch["active"] = False
            changed = True
    if changed:
        save_mandatory_join(data)
    return changed

