def _fmt_price(n):
    try:
        return f"{int(round(n)):,}"
    except Exception:
        return str(n)


def _fmt_coins(n):
    try:
        n = float(n)
        if n == int(n):
            return str(int(n))
        return f"{n:.2f}".rstrip("0").rstrip(".")
    except Exception:
        return str(n)


def _to_jalali(gy, gm, gd):
    g_days_in_month = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
    j_days_in_month = [31, 31, 31, 31, 31, 31, 30, 30, 30, 30, 30, 29]
    gy2 = gy - 1600
    gm2 = gm - 1
    gd2 = gd - 1
    g_day_no = 365 * gy2 + (gy2 + 3) // 4 - (gy2 + 99) // 100 + (gy2 + 399) // 400
    for i in range(gm2):
        g_day_no += g_days_in_month[i]
    if gm2 > 1 and ((gy % 4 == 0 and gy % 100 != 0) or (gy % 400 == 0)):
        g_day_no += 1
    g_day_no += gd2
    j_day_no = g_day_no - 79
    j_np = j_day_no // 12053
    j_day_no %= 12053
    jy = 979 + 33 * j_np + 4 * (j_day_no // 1461)
    j_day_no %= 1461
    if j_day_no >= 366:
        jy += (j_day_no - 1) // 365
        j_day_no = (j_day_no - 1) % 365
    jm = 12
    jd = j_day_no + 1
    for i in range(11):
        if j_day_no < j_days_in_month[i]:
            jm = i + 1
            jd = j_day_no + 1
            break
        j_day_no -= j_days_in_month[i]
    return jy, jm, jd


def _fmt_jalali_datetime(dt):
    jy, jm, jd = _to_jalali(dt.year, dt.month, dt.day)
    return f"{jy:04d}/{jm:02d}/{jd:02d} - {dt.hour:02d}:{dt.minute:02d}:{dt.second:02d}"


def _from_jalali(jy, jm, jd):
    jy += 1595
    days = -355668 + (365 * jy) + ((jy // 33) * 8) + (((jy % 33) + 3) // 4) + jd + (
        ((jm - 1) * 31) if (jm < 7) else (((jm - 7) * 30) + 186))
    gy = 400 * (days // 146097)
    days %= 146097
    if days > 36524:
        days -= 1
        gy += 100 * (days // 36524)
        days %= 36524
        if days >= 365:
            days += 1
    gy += 4 * (days // 1461)
    days %= 1461
    if days > 365:
        gy += (days - 1) // 365
        days = (days - 1) % 365
    gd = days + 1
    sal_a = [0, 31, 29 if (gy % 4 == 0 and (gy % 100 != 0 or gy % 400 == 0)) else 28,
             31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
    gm = 0
    for i in range(1, 13):
        v = sal_a[i]
        if gd <= v:
            gm = i
            break
        gd -= v
    return gy, gm, gd


_JALALI_DATE_RE = re.compile(r"^(\d{4})/(\d{1,2})/(\d{1,2})$")
_CLOCK_TIME_RE = re.compile(r"^([01]?\d|2[0-3]):([0-5]\d)$")


def parse_jalali_date_to_gregorian(text):
    """'1400/01/01' -> date(...) یا None اگر فرمت/مقدار نامعتبر بود."""
    m = _JALALI_DATE_RE.match(text.strip())
    if not m:
        return None
    jy, jm, jd = int(m.group(1)), int(m.group(2)), int(m.group(3))
    if not (1 <= jm <= 12) or not (1 <= jd <= 31):
        return None
    try:
        gy, gm, gd = _from_jalali(jy, jm, jd)
        return date(gy, gm, gd)
    except Exception:
        return None


def parse_clock_time(text):
    """'20:00' -> (hour, minute) یا None اگر فرمت نامعتبر بود."""
    m = _CLOCK_TIME_RE.match(text.strip())
    if not m:
        return None
    return int(m.group(1)), int(m.group(2))

