CONTESTS_FILE = "contests_data.json"
_contests_lock = threading.Lock()

def load_contests():
    with _contests_lock:
        return db.load_json(CONTESTS_FILE, lambda: {"contests": [], "next_id": 1})

def save_contests(data):
    with _contests_lock:
        db.save_json(CONTESTS_FILE, data)

def get_contest(contest_id):
    data = load_contests()
    return next((c for c in data["contests"] if c["id"] == contest_id), None)

def _save_contest(contest):
    data = load_contests()
    for i, c in enumerate(data["contests"]):
        if c["id"] == contest["id"]:
            data["contests"][i] = contest
            save_contests(data)
            return
    data["contests"].append(contest)
    save_contests(data)

def create_contest(ctype, **fields):
    data = load_contests()
    cid = data["next_id"]
    data["next_id"] += 1
    contest = {
        "id": cid, "type": ctype, "status": "active",
        "created_at": datetime.now().isoformat(), "ended_at": None,
        "participants": {}, "message_ids": {}, "result": None, "winners": [],
    }
    contest.update(fields)
    data["contests"].append(contest)
    save_contests(data)
    return contest

def contest_deadline_passed(contest):
    dl = contest.get("deadline")
    if not dl:
        return False
    try:
        return datetime.now() >= datetime.fromisoformat(dl)
    except Exception:
        return False

