def create_pending_payment(user_id, purchase_type, amount_toman, extra=None):
    """ثبت یک پرداخت در انتظار (کیف پول بله) و برگرداندن توکن یکتا برای payload فاکتور."""
    data = load_pending_payments()
    token = uuid.uuid4().hex[:24]
    data.setdefault("payments", {})[token] = {
        "token": token, "user_id": user_id, "purchase_type": purchase_type,
        "amount_toman": amount_toman, "extra": extra or {},
        "status": "pending", "created_at": datetime.now().isoformat(),
    }
    save_pending_payments(data)
    return token

def get_pending_payment(token):
    return load_pending_payments().get("payments", {}).get(token)

def mark_pending_payment_paid(token):
    data = load_pending_payments()
    if token in data.get("payments", {}):
        data["payments"][token]["status"] = "paid"
        data["payments"][token]["paid_at"] = datetime.now().isoformat()
        save_pending_payments(data)
        return data["payments"][token]
    return None

