def get_wallet_meta(purchase_key):
    lookup_key = purchase_key.split(":", 1)[1] if purchase_key.startswith("svc:") else purchase_key
    data = load_settings()
    meta = data.get("wallet_payment_meta", {})
    if lookup_key in meta:
        return meta[lookup_key]
    return _DEFAULT_WALLET_META.get(lookup_key, {"label": lookup_key, "photo_url": None})

def set_wallet_meta(purchase_key, label=None, photo_url=None):
    lookup_key = purchase_key.split(":", 1)[1] if purchase_key.startswith("svc:") else purchase_key
    data = load_settings()
    meta = data.get("wallet_payment_meta", {})
    current = dict(meta.get(lookup_key) or _DEFAULT_WALLET_META.get(lookup_key, {}))
    if label is not None:
        current["label"] = label
    if photo_url is not None:
        current["photo_url"] = photo_url
    meta[lookup_key] = current
    data["wallet_payment_meta"] = meta
    save_settings(data)

