def handle_successful_payment(chat_id, user_id, successful_payment):
    """وقتی کاربر از طریق کیف پول بله پرداخت را با موفقیت انجام داد، این تابع صدا زده می‌شود."""
    token = successful_payment.get("invoice_payload")
    if not token:
        return
    pending = get_pending_payment(token)
    if not pending or pending.get("status") == "paid":
        return  # قبلاً پردازش شده یا نامعتبر است — از پردازش دوباره جلوگیری می‌کنیم
    mark_pending_payment_paid(token)

    purchase_type = pending["purchase_type"]
    amount = pending["amount_toman"]
    extra = pending.get("extra", {})
    lang = _get_user_lang(user_id)
    t = _T(lang)
    users = load_users()
    uid = str(user_id)
    _get_or_init_user(users, uid)
    admin_at = _T(_get_user_lang(ADMIN_ID))
    username = users[uid].get("username")
    alpha_tag = f"@{username}" if username else admin_at("no_username_placeholder")
    now_str = _fmt_jalali_datetime(datetime.now())

    if purchase_type == "coin":
        coins = extra.get("coins", 0)
        purchases = load_purchases()
        pid = purchases.get("next_id", 1)
        purchases["next_id"] = pid + 1
        purchases.setdefault("purchases", []).append({
            "id": pid, "user_id": user_id, "coins": coins,
            "price_str": f"{int(amount):,}", "status": "approved",
            "created_at": datetime.now().isoformat(), "via": "wallet",
        })
        save_purchases(purchases)
        users[uid]["coins"] = round(users[uid].get("coins", 0) + coins, 2)
        save_users(users)
        user_name = _get_user_display_name(users, uid)
        lb_record_purchase(user_id, user_name, amount, users[uid]["coins"])
        bale_api.send_message(chat_id, t("wallet_payment_confirmed"), reply_markup=_build_menu(user_id, lang))
        bale_api.send_message(chat_id, t("coins_received").format(coins=_fmt_coins(coins), purchase_id=pid))
        bale_api.send_message(ADMIN_ID,
            admin_at("admin_auto_coin_payment").format(
                alpha_tag=alpha_tag, user_id=user_id, coins=coins,
                price=_fmt_price(amount), date=now_str))
        return

    if purchase_type == "vip":
        days = extra.get("days", 0)
        vip_data = load_vip_purchases()
        vid = vip_data.get("next_id", 1)
        vip_data["next_id"] = vid + 1
        vip_data.setdefault("purchases", []).append({
            "id": vid, "user_id": user_id, "days": days,
            "price_str": f"{int(amount):,}", "status": "approved",
            "created_at": datetime.now().isoformat(), "via": "wallet",
        })
        save_vip_purchases(vip_data)
        now = datetime.now()
        try:
            current = datetime.fromisoformat(users[uid].get("vip_until", ""))
            base = max(current, now)
        except Exception:
            base = now
        vip_until = base + timedelta(days=days)
        users[uid]["vip_until"] = vip_until.isoformat()
        users[uid]["is_vip"] = True
        vip_gift = get_vip_purchase_gift_coins()
        if vip_gift > 0:
            users[uid]["coins"] = round(users[uid].get("coins", 0) + vip_gift, 2)
        save_users(users)
        user_name = _get_user_display_name(users, uid)
        lb_record_purchase(user_id, user_name, amount, users[uid]["coins"])
        bale_api.send_message(chat_id, t("wallet_payment_confirmed"), reply_markup=_build_menu(user_id, lang))
        if vip_gift > 0:
            bale_api.send_message(chat_id, t("vip_confirmed").format(gift=_fmt_coins(vip_gift)))
        else:
            bale_api.send_message(chat_id, t("vip_confirmed_no_gift"))
        bale_api.send_message(chat_id, t("vip_activated").format(days=days))
        bale_api.send_message(ADMIN_ID,
            admin_at("admin_auto_vip_payment").format(
                alpha_tag=alpha_tag, user_id=user_id, days=days,
                vip_until=_fmt_jalali_datetime(vip_until),
                price=_fmt_price(amount), date=now_str))
        return

    if purchase_type == "ad":
        ad_id = extra.get("ad_id")
        ads = load_ads()
        ad = next((a for a in ads["ads"] if a["id"] == ad_id), None)
        if not ad or ad["status"] != "waiting_payment":
            return
        ad["status"] = "pending_approval"
        save_ads(ads)

        users[uid]["state"] = "idle"
        users[uid].pop("pending_ad_id", None)
        users[uid].pop("pending_ad_days", None)
        save_users(users)

        bale_api.send_message(chat_id, t("wallet_payment_confirmed"), reply_markup=_build_menu(user_id, lang))
        bale_api.send_message(
            chat_id,
            t("ad_confirmed_user_msg").format(days=ad['days'])
        )
        bale_api.send_message(ADMIN_ID,
            admin_at("admin_auto_ad_payment").format(
                ad_id=ad_id, alpha_tag=alpha_tag, user_id=user_id,
                days=ad['days'], price=_fmt_price(amount), date=now_str))
        threading.Thread(target=_publish_ad_to_channel, args=(ad_id,), daemon=True).start()
        return

    # ─── سایر خریدها: پرداخت تأیید شد ولی همچنان نیاز به تأیید ادمین دارد ───
    bale_api.send_message(chat_id, t("wallet_payment_confirmed_wait_admin"), reply_markup=_build_menu(user_id, lang))
    synthetic_msg = {"text": admin_at("wallet_receipt_auto_text")}
    if purchase_type == "mjoin":
        handle_mjoin_receipt_input(chat_id, user_id, synthetic_msg)
    elif purchase_type == "photo_design":
        handle_photo_design_receipt_input(chat_id, user_id, synthetic_msg)
    elif purchase_type.startswith("svc:"):
        handle_svc_receipt_input(chat_id, user_id, synthetic_msg)


def _parse_two_teams(text):
    lines = [l.strip() for l in text.strip().split("\n") if l.strip()]
    if len(lines) != 2:
        return None
    m1 = re.match(r"^1\s*-\s*(.+)$", lines[0])
    m2 = re.match(r"^2\s*-\s*(.+)$", lines[1])
    if not m1 or not m2:
        return None
    t1, t2 = m1.group(1).strip(), m2.group(1).strip()
    if not t1 or not t2:
        return None
    return t1, t2


def _parse_team_list(text, expected_count):
    lines = [l.strip() for l in text.strip().split("\n") if l.strip()]
    if len(lines) != expected_count:
        return None
    teams = []
    for i, line in enumerate(lines, start=1):
        m = re.match(rf"^{i}\s*-\s*(.+)$", line)
        if not m:
            return None
        name = m.group(1).strip()
        if not name:
            return None
        teams.append(name)
    return teams


