def build_league_vote_keyboard(contest):
    cid = contest["id"]
    teams = contest.get("teams", [])
    rows = []
    for i in range(0, len(teams), 3):
        chunk = teams[i:i+3]
        rows.append([{"text": tm, "callback_data": f"pd_vote:{cid}:{i+j}"} for j, tm in enumerate(chunk)])
    return {"inline_keyboard": rows}


def get_eligible_lottery_users(category):
    """برمی‌گرداند لیست آیدی کاربران واجد شرایط قرعه‌کشی بر اساس دسته‌بندی."""
    users = load_users()
    if category == "all":
        return list(users.keys())
    if category == "vip":
        return [uid for uid, u in users.items() if u.get("is_vip")]
    if category == "special":
        active_ids = set()
        for p in load_purchases().get("purchases", []):
            if p.get("status") == "approved":
                active_ids.add(str(p.get("user_id")))
        for p in load_vip_purchases().get("purchases", []):
            if p.get("status") == "approved":
                active_ids.add(str(p.get("user_id")))
        for o in load_service_orders().get("orders", []):
            if o.get("status") == "approved":
                active_ids.add(str(o.get("user_id")))
        for o in load_photo_orders().get("orders", []):
            if o.get("status") in ("approved", "delivered"):
                active_ids.add(str(o.get("user_id")))
        for uid, u in users.items():
            if u.get("referrals", 0) > 0:
                active_ids.add(uid)
        return [uid for uid in active_ids if uid in users]
    return []


def _send_active_predictions_to_user(user_id, user_lang):
    """
    اگر مسابقه‌ی پیش‌بینی (بازی یا قهرمان لیگ) فعالی وجود داشته باشد که هنوز
    زمانش تمام نشده، پیام آن مسابقه برای کاربر (که تازه به ربات اضافه شده و
    قبلاً این پیام را دریافت نکرده) ارسال می‌شود تا بتواند در آن شرکت کند.
    """
    try:
        uid_str = str(user_id)
        data = load_contests()
        for contest in data.get("contests", []):
            if contest.get("type") not in ("match_prediction", "league_prediction"):
                continue
            if contest.get("status") != "active":
                continue
            if contest_deadline_passed(contest):
                continue
            message_ids = contest.get("message_ids", {})
            if uid_str in message_ids:
                continue
            caption = contest.get("description", "")
            if contest["type"] == "match_prediction":
                kb = build_match_vote_keyboard(contest, user_lang)
            else:
                kb = build_league_vote_keyboard(contest)
            res = bale_api.send_photo_with_caption(user_id, contest["poster_file_id"], caption, reply_markup=kb)
            mid = None
            if isinstance(res, dict):
                mid = res.get("result", {}).get("message_id")
            if mid:
                message_ids[uid_str] = mid
                contest["message_ids"] = message_ids
                _save_contest(contest)
    except Exception as e:
        print(f"[send_active_predictions] {e}")


def broadcast_contest(contest):
    """پیام مسابقه را برای همه‌ی کاربران ربات ارسال می‌کند و شناسه پیام هرکدام را ذخیره می‌کند."""
    users = load_users()
    if contest["type"] not in ("match_prediction", "league_prediction"):
        return
    caption = contest.get("description", "")
    message_ids = {}
    for uid_str in list(users.keys()):
        try:
            uid = int(uid_str)
        except Exception:
            continue
        try:
            user_lang = users.get(uid_str, {}).get("lang", "fa")
            if contest["type"] == "match_prediction":
                kb = build_match_vote_keyboard(contest, user_lang)
            else:
                kb = build_league_vote_keyboard(contest)
            res = bale_api.send_photo_with_caption(uid, contest["poster_file_id"], caption, reply_markup=kb)
            mid = None
            if isinstance(res, dict):
                mid = res.get("result", {}).get("message_id")
            if mid:
                message_ids[uid_str] = mid
        except Exception:
            continue
    contest["message_ids"] = message_ids
    _save_contest(contest)


