def _render_svc_banner(service_key, lang):
    """بنر خدمت را با قیمت فعلی (احتمالاً تغییر داده‌شده توسط ادمین) نمایش می‌دهد"""
    svc = SERVICE_CATALOG.get(service_key)
    if not svc:
        return ""
    banner = svc["banner"].get(lang, svc["banner"]["fa"])
    default_price = svc["price_per_1000"]
    current_price = get_svc_price(service_key)
    if current_price != default_price:
        old_str = f"{default_price:,}"
        new_str = f"{current_price:,}"
        banner = banner.replace(old_str, new_str)
    return banner


