def handle_svc_amount_input(chat_id, user_id, text):
    lang = _get_user_lang(user_id)
    t = _T(lang)
    users = load_users()
    uid = str(user_id)
    u = _get_or_init_user(users, uid)
    pending = u.get("pending_svc", {})
    service_key = pending.get("service_key")
    svc = SERVICE_CATALOG.get(service_key)
    if not svc:
        u["state"] = "idle"
        save_users(users)
        return
    unit = _svc_unit(service_key, lang)
    if not text.strip().isdigit():
        bale_api.send_message(chat_id, t("svc_only_number").format(min=svc["min"]), reply_markup=build_back_keyboard(lang))
        return
    amount = int(text.strip())
    if amount < svc["min"]:
        bale_api.send_message(chat_id, t("svc_min_error").format(unit=unit, min=svc["min"]), reply_markup=build_back_keyboard(lang))
        return
    if amount > svc["max"]:
        bale_api.send_message(chat_id, t("svc_max_error").format(unit=unit, max=svc["max"]), reply_markup=build_back_keyboard(lang))
        return
    pending["amount"] = amount
    u["pending_svc"] = pending
    u["state"] = "waiting_for_svc_link"
    save_users(users)
    link_key = "svc_link_prompt_channel" if svc["link_type"] == "channel" else "svc_link_prompt_post"
    bale_api.send_message(chat_id, t(link_key), reply_markup=build_back_keyboard(lang))


_CHANNEL_LINK_RE = re.compile(r"^@[A-Za-z0-9_]{3,64}$")
_POST_LINK_RE = re.compile(r"^https://ble\.ir/[A-Za-z0-9_]+/\d+/\d+/?$")


def handle_svc_link_input(chat_id, user_id, text):
    lang = _get_user_lang(user_id)
    t = _T(lang)
    users = load_users()
    uid = str(user_id)
    u = _get_or_init_user(users, uid)
    pending = u.get("pending_svc", {})
    service_key = pending.get("service_key")
    svc = SERVICE_CATALOG.get(service_key)
    if not svc or "amount" not in pending:
        u["state"] = "idle"
        save_users(users)
        return
    link = text.strip()
    if svc["link_type"] == "channel":
        if not _CHANNEL_LINK_RE.match(link):
            bale_api.send_message(chat_id, t("svc_link_invalid_channel"), reply_markup=build_back_keyboard(lang))
            return
    else:
        if not _POST_LINK_RE.match(link):
            bale_api.send_message(chat_id, t("svc_link_invalid_post"), reply_markup=build_back_keyboard(lang))
            return
    pending["link"] = link
    u["pending_svc"] = pending
    save_users(users)
    amount = pending["amount"]
    unit = _svc_unit(service_key, lang)
    note1 = _svc_note1(service_key, lang)
    note2 = t("svc_note2")
    link_label = _svc_link_label(service_key, lang)
    summary = t("svc_confirm_summary").format(
        note1=note1, note2=note2, unit=unit, amount=amount, link_label=link_label, link=link)
    bale_api.send_message(chat_id, summary, reply_markup=build_svc_confirm_keyboard(service_key, lang))


def _svc_confirm_or_edit(chat_id, user_id, callback_query_id, service_key, confirm):
    lang = _get_user_lang(user_id)
    t = _T(lang)
    users = load_users()
    uid = str(user_id)
    u = _get_or_init_user(users, uid)
    pending = u.get("pending_svc", {})
    if pending.get("service_key") != service_key or "link" not in pending:
        bale_api.answer_callback_query(callback_query_id, t("toast_order_already_processed"))
        return
    if not confirm:
        u["state"] = "waiting_for_svc_amount"
        u["pending_svc"] = {"service_key": service_key}
        save_users(users)
        bale_api.answer_callback_query(callback_query_id)
        banner = _render_svc_banner(service_key, lang)
        bale_api.send_message(chat_id, banner, reply_markup=build_back_keyboard(lang))
        return
    svc = SERVICE_CATALOG.get(service_key)
    amount = pending["amount"]
    price = amount * get_svc_price(service_key) / 1000
    pending["price"] = price
    u["pending_svc"] = pending
    u["state"] = "waiting_for_svc_receipt"
    save_users(users)
    bale_api.answer_callback_query(callback_query_id)
    send_payment_method_choice(chat_id, user_id, f"svc:{service_key}", lang)


def handle_svc_receipt_input(chat_id, user_id, message):
    lang = _get_user_lang(user_id)
    t = _T(lang)
    users = load_users()
    uid = str(user_id)
    u = _get_or_init_user(users, uid)
    pending = u.get("pending_svc", {})
    service_key = pending.get("service_key")
    svc = SERVICE_CATALOG.get(service_key)
    if not svc or "price" not in pending:
        u["state"] = "idle"
        save_users(users)
        return
    photo = message.get("photo")
