def _svc_admin_approve_or_reject(chat_id, user_id, callback_query_id, order_id, approve):
    admin_lang0 = _get_user_lang(user_id)
    at0 = _T(admin_lang0)
    if not is_admin_user(user_id):
        bale_api.answer_callback_query(callback_query_id, at0("toast_not_admin"))
        return
    orders = load_service_orders()
    order = next((o for o in orders["orders"] if o["id"] == order_id), None)
    if not order or order["status"] != "pending":
        bale_api.answer_callback_query(callback_query_id, at0("toast_already_reviewed"))
        return
    buyer_id = order["user_id"]
    buyer_lang = _get_user_lang(buyer_id)
    bt = _T(buyer_lang)
    service_key = order["service_key"]
    unit = _svc_unit(service_key, buyer_lang)
    if approve:
        order["status"] = "approved"
        save_service_orders(orders)
        admin_lang = _get_user_lang(ADMIN_ID)
        at = _T(admin_lang)
        bale_api.answer_callback_query(callback_query_id, at0("toast_svc_approved"))
        bale_api.send_message(ADMIN_ID, at("svc_admin_completed"))
        full_name = _svc_full_name(service_key, buyer_lang)
        date_str = _fmt_jalali_datetime(datetime.now())
        try:
            users = load_users()
            buyer_id_str = str(buyer_id)
            _get_or_init_user(users, buyer_id_str)
            user_name = _get_user_display_name(users, buyer_id_str)
            lb_record_purchase(int(buyer_id), user_name, float(order["price"]), users[buyer_id_str].get("coins", 0))
        except Exception as e:
            print(f"[lb_record_purchase svc] {e}")
        bale_api.send_message(buyer_id,
            bt("svc_completed_user").format(
                full_name=full_name, amount=order["amount"], unit=unit,
                price=_fmt_price(order["price"]), date=date_str),
            reply_markup=_build_menu(buyer_id, buyer_lang))
    else:
        order["status"] = "rejected"
        save_service_orders(orders)
        bale_api.answer_callback_query(callback_query_id, at0("toast_svc_rejected"))
        bale_api.send_message(buyer_id,
            bt("svc_rejected").format(amount=order["amount"], unit=unit),
            reply_markup=_build_menu(buyer_id, buyer_lang))


