def _mjoin_admin_approve_or_reject(chat_id, user_id, callback_query_id, purchase_id, approve):
    admin_lang = _get_user_lang(ADMIN_ID)
    at = _T(admin_lang)
    admin_lang0 = _get_user_lang(user_id)
    at0 = _T(admin_lang0)
    if not is_admin_user(user_id):
        bale_api.answer_callback_query(callback_query_id, at0("toast_not_admin"))
        return
    data = load_mandatory_join()
    purchase = next((p for p in data["purchases"] if p["id"] == purchase_id), None)
    if not purchase or purchase["status"] != "pending":
        bale_api.answer_callback_query(callback_query_id, at0("toast_already_reviewed"))
        return
    buyer_id = purchase["user_id"]
    buyer_lang = _get_user_lang(buyer_id)
    bt = _T(buyer_lang)
    if approve:
        purchase["status"] = "approved"
        days = purchase["days"]
        now = datetime.now()
        expires_at = now + timedelta(days=days)
        new_ch_id = max([c.get("id", 0) for c in data.get("channels", [])], default=0) + 1
        data["channels"].append({
            "id": new_ch_id,
            "channel_username": purchase["channel"],
            "user_id": buyer_id,
            "purchase_id": purchase_id,
            "days": days,
            "created_at": now.isoformat(),
            "expires_at": expires_at.isoformat(),
            "active": True,
        })
        save_mandatory_join(data)
        bale_api.answer_callback_query(callback_query_id, at0("toast_mjoin_approved"))
        end_date_str = _fmt_jalali_datetime(expires_at)
        try:
            users = load_users()
            buyer_id_str = str(buyer_id)
            _get_or_init_user(users, buyer_id_str)
            user_name = _get_user_display_name(users, buyer_id_str)
            lb_record_purchase(int(buyer_id), user_name, float(purchase["price"]), users[buyer_id_str].get("coins", 0))
        except Exception as e:
            print(f"[lb_record_purchase mjoin] {e}")
        bale_api.send_message(ADMIN_ID, at("mjoin_admin_approved").format(end_date=end_date_str))
        bale_api.send_message(buyer_id,
            bt("mjoin_approved_user").format(days=days),
            reply_markup=_build_menu(buyer_id, buyer_lang))
    else:
        purchase["status"] = "rejected"
        save_mandatory_join(data)
        bale_api.answer_callback_query(callback_query_id, at0("toast_mjoin_rejected"))
        bale_api.send_message(ADMIN_ID, at("mjoin_admin_rejected"))
        bale_api.send_message(buyer_id,
            bt("mjoin_rejected_user"),
            reply_markup=_build_menu(buyer_id, buyer_lang))


def mandatory_join_checker():
    """هر 3 ثانیه چک می‌کند: انقضای مدت یا از دست رفتن ادمینی ربات → حذف کامل و دائمی از جوین اجباری."""
    while True:
        try:
            data = load_mandatory_join()
            changed = False
            now = datetime.now()
            for ch in data.get("channels", []):
                if not ch.get("active"):
                    continue
                expired = False
                try:
                    expired = now >= datetime.fromisoformat(ch["expires_at"])
                except Exception:
                    pass
                still_admin = False
                if not expired:
                    try:
                        still_admin = is_bot_admin_in_channel(ch["channel_username"])
                    except Exception:
                        still_admin = False
                if expired or not still_admin:
                    ch["active"] = False
                    changed = True
            if changed:
                save_mandatory_join(data)
        except Exception as e:
            print(f"[mjoin_checker] {e}")
        time.sleep(3)

 
