def _user_full_info(user_id):
    """Build full user info text for support panel (in the ADMIN's language)."""
    admin_lang = _get_user_lang(ADMIN_ID)
    at = _T(admin_lang)
    users = load_users()
    orders = load_orders()
    svc_orders = load_service_orders()
    uid = str(user_id)
    u = users.get(uid, {})
    # orders
    u_orders = [o for o in orders.get("orders", []) if o.get("user_id") == user_id]
    done_orders = sum(1 for o in u_orders if o.get("status") == "completed")
    active_orders = sum(1 for o in u_orders if o.get("status") == "active")
    # service orders (ممبر-لایک-سین چندسکویی)
    u_svc = [s for s in svc_orders.get("orders", []) if s.get("user_id") == user_id]
    done_svc = sum(1 for s in u_svc if s.get("status") == "approved")
    pending_svc = sum(1 for s in u_svc if s.get("status") in ("pending", "pending_payment"))
    # vip
    vip = at("vip_tag") if _is_vip(uid, users) else at("normal_tag")
    # support stats
    sup_count    = u.get("support_msg_count", 0)
    sup_rating   = u.get("support_rating_avg", None)
    rating_str   = f"{sup_rating:.1f}" if sup_rating else at("no_rating_yet")
    spins_avail  = _available_wheel_spins(u)
    spins_used   = u.get("wheel_spins_used", 0)
    _raw_joined  = u.get("joined_at")
    try:
        join_date = _fmt_jalali_datetime(datetime.fromisoformat(_raw_joined))
    except Exception:
        join_date = at("unknown_placeholder")
    left_others  = u.get("left_others_count", 0)
    left_mine    = u.get("left_my_channel_count", 0)
    reported_by  = u.get("report_count_received", 0)
    reported_others = u.get("report_count_sent", 0)
    rep_approved = u.get("reports_approved", 0)
    rep_rejected = u.get("reports_rejected", 0)
    name = u.get("first_name") or at("no_username_placeholder")
    username = u.get("username") or at("no_username_placeholder")
    lang = u.get("lang", "fa")
    return at("user_full_info_template").format(
        name=name, username=username, user_id=user_id, lang=lang,
        coins=u.get('coins', 0), vip=vip, join_date=join_date,
        done_orders=done_orders, active_orders=active_orders,
        done_svc=done_svc, pending_svc=pending_svc,
        referrals=u.get('referrals', 0), left_others=left_others, left_mine=left_mine,
        reported_by=reported_by, reported_others=reported_others,
        rep_approved=rep_approved, rep_rejected=rep_rejected,
        rating_str=rating_str, spins_avail=spins_avail, spins_used=spins_used,
        sup_count=sup_count,
    )

