def handle_support_message(chat_id, user_id, message, from_obj=None):
    """Forward user message to admin with full info."""
    lang = _get_user_lang(user_id)
    t = _T(lang)
    users = load_users()
    uid = str(user_id)
    u = _get_or_init_user(users, uid)
    if u.get("is_blocked"):
        return
    ticket_id = _next_ticket_id()
    u["state"] = "idle"
    u["support_msg_count"] = u.get("support_msg_count", 0) + 1
    save_users(users)
    # tell user
    bale_api.send_message(chat_id, t("support_sent"), reply_markup=_build_menu(user_id, lang))
    # build admin message (نمای کوتاه پیش‌فرض)
    admin_lang = _get_user_lang(ADMIN_ID)
    at = _T(admin_lang)
    msg_text = message.get("text") or message.get("caption") or at("media_no_text_placeholder")
    admin_header = _build_short_ticket_text(ticket_id, msg_text)
    # forward media or text
    photo = message.get("photo")
    video = message.get("video")
    audio = message.get("audio")
    voice = message.get("voice")
    doc   = message.get("document")
    admin_msg_kind = "text"
    if photo:
        sent = bale_api.send_photo(ADMIN_ID, photo[-1]["file_id"], admin_header,
                                   reply_markup=_build_admin_support_keyboard(ticket_id))
        admin_msg_kind = "caption"
    elif video:
        sent = bale_api.send_video(ADMIN_ID, video["file_id"], admin_header,
                                   reply_markup=_build_admin_support_keyboard(ticket_id))
        admin_msg_kind = "caption"
    elif voice:
        bale_api.send_voice(ADMIN_ID, voice["file_id"])
        sent = bale_api.send_message(ADMIN_ID, admin_header,
                                     reply_markup=_build_admin_support_keyboard(ticket_id))
        admin_msg_kind = "text"
    elif audio:
        bale_api.send_audio(ADMIN_ID, audio["file_id"])
        sent = bale_api.send_message(ADMIN_ID, admin_header,
                                     reply_markup=_build_admin_support_keyboard(ticket_id))
        admin_msg_kind = "text"
    elif doc:
        sent = bale_api.send_document(ADMIN_ID, doc["file_id"], admin_header,
                                      reply_markup=_build_admin_support_keyboard(ticket_id))
        admin_msg_kind = "caption"
    else:
        sent = bale_api.send_message(ADMIN_ID, admin_header,
                                     reply_markup=_build_admin_support_keyboard(ticket_id))
        admin_msg_kind = "text"
    admin_msg_id = None
    try:
        if isinstance(sent, dict):
            admin_msg_id = sent.get("result", {}).get("message_id")
    except Exception:
        admin_msg_id = None
    # store session
    with _support_lock:
        _support_sessions[ticket_id] = {
            "user_id": user_id,
            "state": "pending",
            "last_admin_msg_id": admin_msg_id,
            "admin_msg_kind": admin_msg_kind,
            "ticket_view": "short",
            "last_user_msg_id": None,
            "rating_sent": False,
            "rejected": False,
            "pending_new_msg": None,
            "last_user_msg_text": msg_text,
            "last_admin_reply": "",
        }

