# ══════════════════════════════════════════════════════════════
#  Spam / Block / Unblock Handlers
# ══════════════════════════════════════════════════════════════

_spam_tracker = {}   # user_id -> [timestamps]
_spam_lock = _threading.Lock()

def check_spam(user_id) -> bool:
    """Returns True if user is spamming (5 msgs in 3 sec). Admins exempt."""
    if is_admin_user(user_id):
        return False
    import time as _time
    now = _time.time()
    with _spam_lock:
        times = _spam_tracker.get(user_id, [])
        times = [t for t in times if now - t < 3]
        times.append(now)
        _spam_tracker[user_id] = times
        return len(times) >= 5

def handle_spam_warning(chat_id, user_id):
    lang = _get_user_lang(user_id)
    t = _T(lang)
    users = load_users()
    uid = str(user_id)
    u = _get_or_init_user(users, uid)
    warns = u.get("spam_warnings", 0) + 1
    u["spam_warnings"] = warns
    u["total_warnings_received"] = u.get("total_warnings_received", 0) + 1
    if warns >= 3:
        u["is_blocked"] = True
        u["block_count"] = u.get("block_count", 0) + 1
        save_users(users)
        bale_api.send_message(chat_id, t("blocked_msg"))
        bale_api.send_message(chat_id, t("blocked_phone_prompt"),
                              reply_markup=build_blocked_phone_keyboard(lang))
    else:
        save_users(users)
        bale_api.send_message(chat_id, t("spam_warning").format(current=warns))

def _normalize_ir_phone(raw):
    """
    شماره تلفن ایرانی رو به فرمت یکسان 98XXXXXXXXXX تبدیل می‌کنه
    (بدون + و بدون صفر اول) تا ذخیره‌سازی و جست‌وجو همیشه یکسان باشه.
    """
    if not raw:
        return ""
    digits = "".join(ch for ch in str(raw) if ch.isdigit())
    if digits.startswith("0098"):
        digits = digits[2:]
    if digits.startswith("98") and len(digits) == 12:
        return digits
    if digits.startswith("0") and len(digits) == 11:
        return "98" + digits[1:]
    if digits.startswith("9") and len(digits) == 10:
        return "98" + digits
    return digits


def handle_phone_contact(chat_id, user_id, contact, from_obj=None):
    """User sent phone number after being blocked."""
    lang = _get_user_lang(user_id)
    t = _T(lang)
    users = load_users()
    uid = str(user_id)
    u = _get_or_init_user(users, uid)
    # پروفایل کاربر (نام/آیدی حرفی) رو تازه می‌کنیم تا در گزارش ادمین "ندارد" نشون داده نشه
    _remember_user_profile(users, uid, from_obj)
    u = users[uid]
    if u.get("perm_blocked"):
        return
    block_count = u.get("block_count", 0)
    if block_count >= 2:
        u["perm_blocked"] = True
        save_users(users)
        bale_api.send_message(chat_id, t("perm_blocked_msg"))
        return
    raw_phone = contact.get("phone_number", "")
    admin_lang = _get_user_lang(ADMIN_ID)
    at = _T(admin_lang)
    phone = _normalize_ir_phone(raw_phone) or raw_phone or at("unknown_placeholder")
    u["phone_number"] = phone
    save_users(users)
    info = _user_full_info(user_id)
    bale_api.send_message(ADMIN_ID,
        at("phone_commitment_header").format(phone=phone, info=info))
    bale_api.send_message(chat_id, t("unblocked_msg"), reply_markup=_build_menu(user_id, lang))
    users = load_users()
    u = users.get(uid, {})
    u["is_blocked"] = False
    # فقط شمارنده‌ی فعال اخطار صفر می‌شه؛ سابقه‌ی کل اخطارها برای گزارش ادمین حفظ می‌شود
    u["spam_warnings"] = 0
    save_users(users)


