def handle_support_callback(callback_data, callback_query_id, admin_chat_id, admin_msg_id):
    """Handle all sup_* and rate:* callbacks."""
    parts = callback_data.split(":")
    action = parts[0]

    # ── Rating ──
    if action == "rate":
        admin_lang0 = _get_user_lang(ADMIN_ID)
        at0 = _T(admin_lang0)
        ticket_id = int(parts[1])
        stars = int(parts[2])
        sess = _support_sessions.get(ticket_id, {})
        user_id = sess.get("user_id")
        if not user_id:
            bale_api.answer_callback_query(callback_query_id, at0("toast_ticket_not_found"))
            return
        users = load_users()
        uid = str(user_id)
        u = _get_or_init_user(users, uid)
        buyer_lang = u.get("lang", "fa")
        bt = _T(buyer_lang)
        # باگ ۹: فقط یک‌بار امتیاز
        if u.get(f"rated_ticket_{ticket_id}"):
            bale_api.answer_callback_query(callback_query_id, bt("toast_already_rated"))
            bale_api.send_message(user_id, bt("already_rated_msg"))
            return
        u[f"rated_ticket_{ticket_id}"] = True
        total = u.get("support_rating_total", 0) + stars
        count = u.get("support_rating_count", 0) + 1
        u["support_rating_total"] = total
        u["support_rating_count"] = count
        u["support_rating_avg"]   = round(total / count, 2)
        save_users(users)
        user_name = u.get("first_name") or at0("no_username_placeholder")
        username  = u.get("username", "")
        user_tag  = f"@{username}" if username else f"#{uid}"
        avg = u["support_rating_avg"]
        # باگ ۹: پیام امتیاز فقط به ADMIN_ID برود نه user_id
        bale_api.send_message(ADMIN_ID,
            at0("rating_received_admin_msg").format(user_name=user_name, user_tag=user_tag, stars=stars, avg=avg, count=count))
        bale_api.send_message(user_id, bt("star_thank_you_msg").format(stars=stars))
        bale_api.answer_callback_query(callback_query_id, at0("toast_rating_saved").format(stars=stars))
        return

    ticket_id = int(parts[1]) if len(parts) > 1 else 0
    sess = _support_sessions.get(ticket_id)
    admin_lang = _get_user_lang(ADMIN_ID)
    at = _T(admin_lang)
    if not sess:
        bale_api.answer_callback_query(callback_query_id, at("toast_ticket_not_found_expired"))
        return
    user_id = sess["user_id"]
    lang = _get_user_lang(user_id)
    t = _T(lang)

    if action == "sup_userinfo":
        bale_api.answer_callback_query(callback_query_id)
        full_text = _build_full_ticket_text(ticket_id, user_id, sess.get("last_user_msg_text", ""))
        kb = _build_admin_support_keyboard(ticket_id, view="full")
        kind = sess.get("admin_msg_kind", "text")
        if admin_msg_id:
            if kind == "caption":
                bale_api.edit_message_caption(admin_chat_id, admin_msg_id, full_text, reply_markup=kb)
            else:
                bale_api.edit_message_text(admin_chat_id, admin_msg_id, full_text, reply_markup=kb)
        else:
            bale_api.send_message(admin_chat_id, full_text, reply_markup=kb)
        sess["ticket_view"] = "full"
        return

    if action == "sup_msgtext":
        bale_api.answer_callback_query(callback_query_id)
        short_text = _build_short_ticket_text(ticket_id, sess.get("last_user_msg_text", ""))
        kb = _build_admin_support_keyboard(ticket_id, view="short")
        kind = sess.get("admin_msg_kind", "text")
        if admin_msg_id:
            if kind == "caption":
                bale_api.edit_message_caption(admin_chat_id, admin_msg_id, short_text, reply_markup=kb)
            else:
                bale_api.edit_message_text(admin_chat_id, admin_msg_id, short_text, reply_markup=kb)
        else:
            bale_api.send_message(admin_chat_id, short_text, reply_markup=kb)
        sess["ticket_view"] = "short"
        return

    if action == "sup_accept":
        if sess.get("accepted"):
            bale_api.answer_callback_query(callback_query_id, at("toast_already_accepted"))
            bale_api.send_message(admin_chat_id, at("already_accepted_msg"))
            return
        if sess.get("rejected") or sess.get("state") == "rejected":
            bale_api.answer_callback_query(callback_query_id, at("toast_already_rejected_ticket"))
            bale_api.send_message(admin_chat_id, at("already_rejected_msg"))
            return
        sess["state"] = "active"
        sess["accepted"] = True
        bale_api.send_message(admin_chat_id, at("accepted_admin_msg"))
        bale_api.answer_callback_query(callback_query_id, at("toast_accepted"))

    elif action == "sup_reject":
        if sess.get("accepted"):
            bale_api.answer_callback_query(callback_query_id, at("toast_already_accepted_ticket"))
            bale_api.send_message(admin_chat_id, at("already_accepted_no_reject_msg"))
            return
        if sess.get("rejected") or sess.get("state") == "rejected":
            bale_api.answer_callback_query(callback_query_id, at("toast_already_rejected"))
            bale_api.send_message(admin_chat_id, at("already_rejected_no_retry_msg"))
            return
        bale_api.send_message(admin_chat_id,
            at("reject_confirm_prompt"),
            reply_markup=_build_admin_reject_confirm_keyboard(ticket_id))
        bale_api.answer_callback_query(callback_query_id, "")

    elif action == "sup_reject_confirm":
        if sess.get("rejected") or sess.get("state") == "rejected":
            bale_api.answer_callback_query(callback_query_id, at("toast_already_rejected"))
            return
        sess["state"] = "rejected"
        sess["rejected"] = True
        sess["waiting_reject_reason"] = True
        bale_api.send_message(admin_chat_id, at("reject_recorded_admin_msg"))
        bale_api.answer_callback_query(callback_query_id, at("toast_rejected"))

    elif action == "sup_reject_cancel":
        bale_api.answer_callback_query(callback_query_id, at("toast_cancelled"))

    elif action == "sup_end":
        if sess.get("state") == "ended":
            bale_api.answer_callback_query(callback_query_id, at("toast_already_ended"))
            return
        bale_api.send_message(admin_chat_id,
            at("end_confirm_prompt"),
            reply_markup=_build_admin_confirm_end_keyboard(ticket_id))
        bale_api.answer_callback_query(callback_query_id, "")

    elif action == "sup_end_confirm":
        if sess.get("state") == "ended":
            bale_api.answer_callback_query(callback_query_id, at("toast_already_ended"))
            return
        sess["state"] = "ended"
        bale_api.send_message(admin_chat_id, at("ended_admin_msg"))
        if not sess.get("rating_sent"):
            sess["rating_sent"] = True
            bale_api.send_message(user_id,
                t("ended_user_msg"),
                reply_markup=_build_rating_keyboard(ticket_id))
        bale_api.answer_callback_query(callback_query_id, at("toast_ended"))

    elif action == "sup_end_cancel":
        bale_api.answer_callback_query(callback_query_id, at("toast_cancelled"))

    elif action == "sup_del":
        msg_id_to_del = int(parts[2]) if len(parts) > 2 else 0
        if msg_id_to_del:
            bale_api.delete_message(user_id, msg_id_to_del)
        bale_api.send_message(admin_chat_id, at("deleted_msg_admin"))
        bale_api.answer_callback_query(callback_query_id, at("toast_deleted"))

    elif action == "sup_edit":
        msg_id_to_edit = int(parts[2]) if len(parts) > 2 else 0
        sess["editing_msg_id"] = msg_id_to_edit
        sess["state"] = "waiting_edit"
        bale_api.send_message(admin_chat_id, at("edit_prompt_admin"))
        bale_api.answer_callback_query(callback_query_id, "")

    elif action == "sup_new":
        sess["state"] = "waiting_new_msg"
        bale_api.send_message(admin_chat_id, at("new_msg_prompt_admin"))
        bale_api.answer_callback_query(callback_query_id, "")

    elif action == "sup_newmsg_confirm":
        pending = sess.get("pending_new_msg")
        if not pending:
            bale_api.answer_callback_query(callback_query_id, at("toast_msg_not_found"))
            return
        formatted_new = t("new_support_msg_template").format(msg=pending)
        sent = bale_api.send_message(user_id, formatted_new)
        new_msg_id = (sent or {}).get("result", {}).get("message_id", 0)
        sess["last_user_msg_id"] = new_msg_id
        sess["pending_new_msg"] = None
        sess["state"] = "active"
        bale_api.send_message(admin_chat_id,
            at("new_msg_sent_admin").format(msg=pending),
            reply_markup=_build_admin_reply_keyboard(ticket_id, new_msg_id))
        bale_api.answer_callback_query(callback_query_id, at("toast_sent"))

    elif action == "sup_newmsg_cancel":
        sess["pending_new_msg"] = None
        sess["state"] = "active"
        bale_api.pin_message(admin_chat_id, admin_msg_id, at("newmsg_cancelled_pin"))
        bale_api.answer_callback_query(callback_query_id, at("toast_cancelled"))

    elif action == "sup_block":
        users = load_users()
        uid = str(user_id)
        u = _get_or_init_user(users, uid)
        if u.get("is_blocked"):
            bale_api.answer_callback_query(callback_query_id, "")
            bale_api.pin_message(admin_chat_id, admin_msg_id, at("already_blocked_pin"))
            return
        bale_api.send_message(admin_chat_id,
            at("block_confirm_prompt"),
            reply_markup=_build_admin_block_confirm_keyboard(ticket_id))
        bale_api.answer_callback_query(callback_query_id, "")

    elif action == "sup_block_confirm":
        users = load_users()
        uid = str(user_id)
        u = _get_or_init_user(users, uid)
        u["is_blocked"] = True
        u["block_count"] = u.get("block_count", 0) + 1
        save_users(users)
        bale_api.send_message(admin_chat_id, at("user_blocked_admin_msg"))
        bale_api.send_message(user_id, t("blocked_msg"))
        bale_api.send_message(user_id, t("blocked_phone_prompt"),
                              reply_markup=build_blocked_phone_keyboard(lang))
        bale_api.answer_callback_query(callback_query_id, at("toast_blocked"))

    elif action == "sup_block_cancel":
        bale_api.answer_callback_query(callback_query_id, at("toast_cancelled"))

    elif action == "sup_unblock":
        users = load_users()
        uid = str(user_id)
        u = _get_or_init_user(users, uid)
        if not u.get("is_blocked"):
            bale_api.answer_callback_query(callback_query_id, "")
            bale_api.pin_message(admin_chat_id, admin_msg_id, at("already_unblocked_pin"))
            return
        u["is_blocked"] = False
        u["spam_warnings"] = 0
        save_users(users)
        bale_api.pin_message(admin_chat_id, admin_msg_id, at("user_unblocked_pin"))
        bale_api.send_message(user_id, t("unblocked_msg"), reply_markup=_build_menu(user_id, lang))
        bale_api.answer_callback_query(callback_query_id, at("toast_unblocked"))


def _is_known_button_text(text):
    """چک می‌کند که آیا متن ارسالی، برچسبِ یکی از دکمه‌های شیشه‌ای/کیبوردی ربات است یا خیر
    (در هر ۴ زبان و در پنل ادمین). برای جلوگیری از ارسال اشتباهیِ کلیک دکمه به‌عنوان پاسخ تیکت."""
    if not text:
        return False
    text = text.strip()
    for lang_dict in LANGS.values():
        for k, v in lang_dict.items():
            if k.startswith("btn_") and v == text:
                return True
    for lang_dict in _ADMIN_TEXTS.values():
        for v in lang_dict.values():
            if isinstance(v, str) and v == text:
                return True
    return False


def handle_admin_message(admin_chat_id, admin_id, message) -> bool:
    """
    فقط state machine پنل ادمین و support reply رو هندل می‌کنه.
    دکمه پنل ادمین در main.py قبلاً چک شده.
    True برمی‌گردونه اگه پیام مصرف شد.
    """
    text = message.get("text", "")
    admin_lang = _get_user_lang(admin_id)
    at = _T(admin_lang)

    # ── باگ مهم: اگر ادمین در حالت پاسخ به تیکت است ولی به‌جای پاسخ، دکمه‌ای از ربات را زده ──
    for ticket_id, sess in list(_support_sessions.items()):
        needs_reply = sess.get("waiting_reject_reason") or sess.get("state") in ("active", "waiting_edit", "waiting_new_msg")
        if needs_reply and _is_known_button_text(text):
            bale_api.send_message(admin_chat_id, at("ticket_lock_warning"))
            return True

    # ── اگر ادمین در حالت انتظار دلیل رد تیکت هست ──
    for ticket_id, sess in list(_support_sessions.items()):
        if sess.get("waiting_reject_reason"):
            return handle_admin_support_reply(admin_chat_id, message)

    # ── ارسال به کانال کاربران: باید قبل از هر پردازش دیگه چک بشه چون هم متن
    #    و هم پیام غیرمتنی (فوروارد/عکس/...) می‌تونه باشه ──
    if _ADMIN_PANEL_LOADED:
        if handle_admin_ucbc_message(admin_chat_id, admin_id, message):
            return True

    # ── ورودی متنی پنل ادمین (state machine) ──
    if _ADMIN_PANEL_LOADED and text:
        if handle_admin_text_input(admin_chat_id, admin_id, text):
            return True

    # ── ورودی غیرمتنی (عکس/فایل/صوت) در حالت‌هایی که فقط متن مجاز است ──
    if _ADMIN_PANEL_LOADED and not text:
        if handle_admin_non_text(admin_chat_id, admin_id, message):
            return True

    # ── پاسخ پشتیبانی ──
    return handle_admin_support_reply(admin_chat_id, message)


def handle_admin_support_reply(admin_chat_id, message):
    """Called when admin sends a message while a support session is active."""
    for ticket_id, sess in list(_support_sessions.items()):
        user_id = sess.get("user_id")
        admin_lang = _get_user_lang(ADMIN_ID)
        at = _T(admin_lang)

        # waiting for reject reason
        if sess.get("waiting_reject_reason"):
            reason = message.get("text", "").strip()
            if not reason:
                # ادمین پیام خالی یا غیر متنی فرستاده
                bale_api.send_message(admin_chat_id, at("reject_reason_empty_warning"))
                return True
            sess["waiting_reject_reason"] = False
            lang = _get_user_lang(user_id)
            t = _T(lang)
            bale_api.send_message(admin_chat_id, at("reject_reason_saved_admin"))
            bale_api.send_message(user_id, t("reject_reason_user_msg").format(reason=reason))
            return True

        # editing a message
        if sess.get("state") == "waiting_edit":
            old_msg_id = sess.get("editing_msg_id", 0)
            new_text = message.get("text", "")
            if old_msg_id:
                bale_api.delete_message(user_id, old_msg_id)
            lang = _get_user_lang(user_id)
            t = _T(lang)
            formatted_edit = t("edited_msg_template").format(msg=new_text)
            sent = bale_api.send_message(user_id, formatted_edit)
            new_msg_id = (sent or {}).get("result", {}).get("message_id", 0)
            sess["last_user_msg_id"] = new_msg_id
            sess["state"] = "active"
            if sess.get("rating_sent"):
                sess["rating_sent"] = False
            bale_api.send_message(admin_chat_id,
                at("msg_edited_admin"),
                reply_markup=_build_admin_reply_keyboard(ticket_id, new_msg_id))
            return True

        # new message confirm step
        if sess.get("state") == "waiting_new_msg":
            pending = message.get("text", "")
            sess["pending_new_msg"] = pending
            sess["state"] = "waiting_new_confirm"
            bale_api.send_message(admin_chat_id,
                at("newmsg_confirm_prompt").format(msg=pending),
                reply_markup=_build_admin_newmsg_confirm_keyboard(ticket_id))
            return True

        # active session — send to user
        if sess.get("state") == "active":
            text = message.get("text", "")
            photo = message.get("photo")
            video = message.get("video")
            voice = message.get("voice")
            doc   = message.get("document")
            lang = _get_user_lang(user_id)
            t = _T(lang)
            # قالب زیبای پیام پشتیبان برای کاربر
            def _sup_caption(extra=""):
                base = t("sup_reply_header")
                return f"{base}\n\n{extra}\n\n@Arka_Member" if extra else f"{base}\n\n@Arka_Member"
            if photo:
                cap = _sup_caption(f"📷 {message.get('caption','')}" if message.get('caption') else t("sup_reply_photo_default"))
                sent = bale_api.send_photo(user_id, photo[-1]["file_id"], cap)
            elif video:
                cap = _sup_caption(f"🎥 {message.get('caption','')}" if message.get('caption') else t("sup_reply_video_default"))
                sent = bale_api.send_video(user_id, video["file_id"], cap)
            elif voice:
                sent = bale_api.send_voice(user_id, voice["file_id"])
                bale_api.send_message(user_id, _sup_caption(t("sup_reply_voice_default")))
            elif doc:
                cap = _sup_caption(f"📎 {message.get('caption','')}" if message.get('caption') else t("sup_reply_doc_default"))
                sent = bale_api.send_document(user_id, doc["file_id"], cap)
            else:
                formatted = f"{t('sup_reply_header')}\n\n{t('sup_reply_text_label')}\n┌─────────────────\n│ {text}\n└─────────────────\n\n@Arka_Member"
                sent = bale_api.send_message(user_id, formatted)
            new_msg_id = (sent or {}).get("result", {}).get("message_id", 0)
            sess["last_user_msg_id"] = new_msg_id
            # ذخیره آخرین پاسخ ادمین برای جستجوی گفتگو
            if text:
                sess["last_admin_reply"] = text
            bale_api.send_message(admin_chat_id,
                at("sup_reply_sent_admin"),
                reply_markup=_build_admin_reply_keyboard(ticket_id, new_msg_id))
            return True
    return False


