def handle_account(chat_id, user_id):
    lang = _get_user_lang(user_id)
    t = _T(lang)
    users = load_users()
    user_id_str = str(user_id)
    user = _get_or_init_user(users, user_id_str)

    name = user.get("first_name") or t("no_username_placeholder")
    coins = round(user.get("coins", 0), 2)
    purchased = user.get("total_purchased_coins", 0)
    username = user.get("username") or t("no_username_placeholder")
    if username != t("no_username_placeholder"):
        username = f"@{username}"
    referrals = user.get("referrals", 0)
    # شمارش سفارشات تکمیل‌شده
    orders_data = load_orders()
    completed_orders = sum(
        1 for o in orders_data["orders"]
        if o["user_id"] == user_id and o.get("status") == "completed"
    )
    vip_status = t("vip_yes") if _is_vip(user_id_str, users) else t("vip_no")

    text = t("account_title").format(
        name=name,
        coins=coins,
        purchased=purchased,
        username=username,
        referrals=referrals,
        orders=completed_orders,
        vip_status=vip_status,
        user_id=user_id,
    )
