def handle_ad_content_input(chat_id, user_id, message):
    """دریافت پیام/فوروارد آگهی از کاربر → ذخیره و ارسال اطلاعات پرداخت"""
    users = load_users()
    user_id_str = str(user_id)
    days = users[user_id_str].get("pending_ad_days")
    if not days:
        return
    pkg = next((p for p in get_ad_packages() if p["days"] == days), None)
    if not pkg:
        return

    ads = load_ads()
    ad_id = ads["next_id"]
    ads["next_id"] += 1

    # ذخیره اطلاعات پیام آگهی
    msg_data = {
        "text": message.get("text") or message.get("caption"),
        "photo": None,
        "forward_from_chat": None,
        "forward_from_message_id": None,
    }
    if message.get("photo"):
        msg_data["photo"] = message["photo"][-1]["file_id"]
    if message.get("forward_from_chat"):
        msg_data["forward_from_chat"] = message["forward_from_chat"].get("id") or message["forward_from_chat"].get("username")
        msg_data["forward_from_message_id"] = message.get("forward_from_message_id")

    ad_record = {
        "id": ad_id,
        "user_id": user_id,
        "days": days,
        "price_str": pkg["price_str"],
        "msg_data": msg_data,
        "status": "waiting_payment",
        "channel_msg_id": None,
        "disclaimer_msg_id": None,
        "created_at": datetime.now().isoformat(),
    }
    ads["ads"].append(ad_record)
    save_ads(ads)

    users[user_id_str]["state"] = "waiting_for_ad_receipt"
    users[user_id_str]["pending_ad_id"] = ad_id
    save_users(users)

    lang = _get_user_lang(user_id)
    t = _T(lang)
    bale_api.send_message(
        chat_id,
        t("ad_content_received").format(price=pkg["price_str"])
    )
    send_payment_method_choice(chat_id, user_id, "ad", lang)

