def _publish_ad_to_channel(ad_id):
    """ارسال آگهی به کانال و زمان‌بندی حذف"""
    ads = load_ads()
    ad = next((a for a in ads["ads"] if a["id"] == ad_id), None)
    if not ad:
        return

    msg_data = ad["msg_data"]
    channel = AD_CHANNEL_USERNAME

    # ارسال پیام آگهی
    sent_msg = None
    if msg_data.get("photo"):
        caption = msg_data.get("text") or ""
        sent_msg = bale_api.send_photo_with_caption(channel, msg_data["photo"], caption)
    elif msg_data.get("text"):
        sent_msg = bale_api.send_message(channel, msg_data["text"])
    else:
        # اگر پیام فوروارد بود و متن نداشت
        sent_msg = bale_api.send_message(channel, "📢 آگهی")

    ad_msg_id = None
    if sent_msg and sent_msg.get("ok"):
        ad_msg_id = sent_msg["result"]["message_id"]

    # ارسال پیام «این پیام تبلیغات است»
    disc_msg = bale_api.send_message(channel, AD_DISCLAIMER_TEXT)
    disc_msg_id = None
    if disc_msg and disc_msg.get("ok"):
        disc_msg_id = disc_msg["result"]["message_id"]

    ad["channel_msg_id"] = ad_msg_id
    ad["disclaimer_msg_id"] = disc_msg_id
    ad["published_at"] = datetime.now().isoformat()
    ad["status"] = "active"
    save_ads(ads)

    # زمان‌بندی حذف
    delay_seconds = ad["days"] * 24 * 3600
    threading.Thread(
        target=_delete_ad_after_delay,
        args=(ad_id, delay_seconds),
        daemon=True
    ).start()


def _delete_ad_after_delay(ad_id, delay_seconds):
    time.sleep(delay_seconds)
    ads = load_ads()
    ad = next((a for a in ads["ads"] if a["id"] == ad_id), None)
    if not ad or ad["status"] != "active":
        return
    channel = AD_CHANNEL_USERNAME
    if ad.get("channel_msg_id"):
        try:
            bale_api.delete_message(channel, ad["channel_msg_id"])
        except Exception as e:
            print(f"[ad_delete] {e}")
    if ad.get("disclaimer_msg_id"):
        try:
            bale_api.delete_message(channel, ad["disclaimer_msg_id"])
        except Exception as e:
            print(f"[ad_delete_disc] {e}")
    ad["status"] = "expired"
    save_ads(ads)


