def handle_receipt_input(chat_id, user_id, message, is_vip_receipt=False):
    users = load_users()
    user_id_str = str(user_id)
    lang = users.get(user_id_str, {}).get("lang", "fa")

    if is_vip_receipt:
        pending = users[user_id_str].get("pending_vip")
        if not pending:
            return
        days = pending["days"]
        price_str = pending["price_str"]
        vip_data = load_vip_purchases()
        vip_id = vip_data["next_id"]
        vip_data["next_id"] += 1
        photo = message.get("photo")
        receipt_file_id = photo[-1]["file_id"] if photo else None
        purchase = {"id": vip_id, "user_id": user_id, "days": days, "price_str": price_str,
                    "status": "pending", "created_at": datetime.now().strftime("%Y-%m-%d %H:%M"),
                    "receipt_file_id": receipt_file_id}
        vip_data["purchases"].append(purchase)
        save_vip_purchases(vip_data)
        users[user_id_str]["state"] = "idle"
        users[user_id_str].pop("pending_vip", None)
        save_users(users)
        t = _T(lang)
        bale_api.send_message(chat_id,
            t("receipt_received_msg").format(tracking_id=vip_id),
            reply_markup=_build_menu(user_id, lang))
        admin_lang = _get_user_lang(ADMIN_ID)
        at = _T(admin_lang)
        admin_text = at("admin_new_vip_request").format(vip_id=vip_id, user_id=user_id, days=days, price_str=price_str)
        if photo:
            bale_api.send_photo_with_caption(ADMIN_ID, photo[-1]["file_id"], admin_text,
                                             reply_markup=build_admin_vip_keyboard(vip_id, admin_lang))
        else:
            bale_api.send_message(ADMIN_ID,
                admin_text + f"\n\n{at('receipt_text_label')}\n{message.get('text', message.get('caption', at('no_text_placeholder')))}",
                reply_markup=build_admin_vip_keyboard(vip_id, admin_lang))
        return
 
    pending_pkg = users[user_id_str].get("pending_purchase")
    if not pending_pkg:
        return
    coins = pending_pkg["coins"]
    price_str = pending_pkg["price_str"]
    purchases = load_purchases()
    purchase_id = purchases["next_id"]
    purchases["next_id"] += 1
    purchase = {"id": purchase_id, "user_id": user_id, "coins": coins, "price_str": price_str,
                "status": "pending", "created_at": datetime.now().isoformat()}
    purchases["purchases"].append(purchase)
    save_purchases(purchases)
    users[user_id_str]["state"] = "idle"
    users[user_id_str].pop("pending_purchase", None)
    save_users(users)
    t = _T(lang)
    bale_api.send_message(chat_id,
        t("receipt_received_msg").format(tracking_id=purchase_id),
        reply_markup=_build_menu(user_id, lang))
    admin_lang = _get_user_lang(ADMIN_ID)
    at = _T(admin_lang)
    admin_text = at("admin_new_coin_request").format(purchase_id=purchase_id, user_id=user_id, coins=coins, price_str=price_str)
    photo = message.get("photo")
    if photo:
        bale_api.send_photo_with_caption(ADMIN_ID, photo[-1]["file_id"], admin_text,
                                         reply_markup=build_admin_purchase_keyboard(purchase_id, admin_lang))
    else:
        bale_api.send_message(ADMIN_ID,
            admin_text + f"\n\n{at('receipt_text_label')}\n{message.get('text', message.get('caption', at('no_text_placeholder')))}",
            reply_markup=build_admin_purchase_keyboard(purchase_id, admin_lang))
 
 
