def _force_cancel_order(order, orders_data, reason_key, extra_fmt=None, notify_owner=True):
    """
    لغو اجباری یک سفارش فعال (توسط خود سیستم، نه با درخواست کاربر):
    - وضعیت سفارش cancelled می‌شود
    - پیام سفارش از کانال حذف می‌شود (رفع باگ باقی‌ماندن سفارش لغوشده در کانال)
    - کل سکه باقی‌مانده سفارش (coins_remaining) به‌طور کامل به صاحب سفارش بازگردانده می‌شود
    - پیام توضیح‌دهنده به زبان خود کاربر برایش ارسال می‌شود
    """
    if order.get("status") != "active":
        return False
    coins_remaining = order.get("coins_remaining", 0)
    order["status"] = "cancelled"
    if order.get("message_id"):
        try:
            bale_api.delete_message(_main_channel_target(), order["message_id"])
        except Exception as e:
            print(f"[force_cancel_delete] {e}")
    save_orders(orders_data)
    owner_id = order["user_id"]
    owner_id_str = str(owner_id)
    users = load_users()
    _get_or_init_user(users, owner_id_str)
    users[owner_id_str]["coins"] = round(users[owner_id_str].get("coins", 0) + coins_remaining, 2)
    save_users(users)
    if notify_owner:
        try:
            owner_lang = _get_user_lang(owner_id)
            ot = _T(owner_lang)
            fmt_args = {"refund": _fmt_coins(coins_remaining)}
            if extra_fmt:
                fmt_args.update(extra_fmt)
            bale_api.send_message(owner_id, ot(reason_key).format(**fmt_args))
        except Exception as e:
            print(f"[force_cancel_notify] {e}")
    return True


def check_negative_balance_and_cancel_orders(user_id_str, users=None):
    """
    اگر سکه کاربر منفی شده باشد، تمامی سفارش‌های فعال او لغو می‌شوند و
    کل سکه باقی‌مانده هر سفارش به او بازگردانده می‌شود (حتی اگر باعث شود
    موجودی همچنان منفی/نزدیک صفر باشد). این جلوی سوءاستفاده از موجودی
    منفی برای گرفتن عضو رایگان و سپس ترک کانال‌ها را می‌گیرد.
    """
    if users is None:
        users = load_users()
    u = users.get(user_id_str)
    if not u or u.get("coins", 0) >= 0:
        return
    try:
        user_id = int(user_id_str)
    except (TypeError, ValueError):
        return
    orders_data = load_orders()
    changed = False
    for order in orders_data.get("orders", []):
        if order.get("status") == "active" and str(order.get("user_id")) == user_id_str:
            if _force_cancel_order(order, orders_data, "order_cancelled_negative_balance"):
                changed = True
    # چون _force_cancel_order خودش orders_data را ذخیره می‌کند، دوباره ذخیره لازم نیست


def check_and_penalty_left_channels(user_id):
    users = load_users()
    user_id_str = str(user_id)
    if user_id_str not in users:
        return
    user_data = users[user_id_str]
    joined_channels = user_data.get("joined_channels", {})
    current_coins = user_data.get("coins", 0)
    changed = False
    now = datetime.now()
    to_remove = []
 
    for channel_id, join_data in list(joined_channels.items()):
        join_time_str = join_data.get("join_time")
        if not join_time_str:
            continue
        join_time = datetime.fromisoformat(join_time_str)
        if now - join_time < timedelta(days=3):
            if not is_user_in_specific_channel(channel_id, user_id):
                # اگر ربات دیگر در این کانال ادمین نیست (یا کانال پیدا نشد)،
                # نمی‌توان با اطمینان گفت کاربر لفت داده؛ پس جریمه نکن.
                if _channel_admin_status(channel_id) != "admin":
                    continue
                current_coins = max(0, current_coins - 2)
                changed = True
                to_remove.append(channel_id)
                try:
                    bale_api.send_message(user_id, LEFT_EARLY_PENALTY_MESSAGE)
                except Exception as e:
                    print(f"[penalty_msg] {e}")
                try:
                    order_id = join_data.get("order_id")
                    if order_id:
                        orders = load_orders()
                        order = next((o for o in orders["orders"] if o["order_id"] == order_id), None)
                        if order and order.get("status") == "active":
                            owner_id = order["user_id"]
                            owner_id_str = str(owner_id)
                            refund_amount = 2
                            if owner_id_str not in users:
                                users[owner_id_str] = {"coins": 0}
                            users[owner_id_str]["coins"] = round(
                                users[owner_id_str].get("coins", 0) + refund_amount, 2)
                            owner_lang = _get_user_lang(owner_id)
                            ot = _T(owner_lang)
                            bale_api.send_message(owner_id,
                                ot("channel_leave_refund_msg").format(refund=refund_amount))
                except Exception as e:
                    print(f"[penalty_owner_msg] {e}")
        else:
            to_remove.append(channel_id)
 
    for ch in to_remove:
        joined_channels.pop(ch, None)
 
    if changed or to_remove:
        users[user_id_str]["coins"] = current_coins
        users[user_id_str]["joined_channels"] = joined_channels
        save_users(users)
        # اگر با این جریمه موجودی کاربر منفی شد، سفارش‌های فعال خودش لغو و سکه باقی‌مانده برگردانده شود
        check_negative_balance_and_cancel_orders(user_id_str)
 
 
