# ══════════════════════════════════════════════════════════════
#  Callback Handler
# ══════════════════════════════════════════════════════════════
 
def handle_callback(callback_query):
    callback_data = callback_query.get("data", "")
    message = callback_query.get("message", {})
    chat_id = message.get("chat", {}).get("id")
    message_id = message.get("message_id", 0)
    from_obj = callback_query.get("from") or {}
    user_id = from_obj.get("id")
    callback_query_id = callback_query.get("id")
    if not chat_id or not user_id:
        return

    if not is_admin_user(user_id):
        if not is_bot_enabled():
            return
        if is_maintenance_mode():
            _maint_lang = _get_user_lang(user_id)
            _maint_t = _T(_maint_lang)
            bale_api.answer_callback_query(callback_query_id, "")
            bale_api.send_message(chat_id, _maint_t("bot_maintenance_msg"))
            return

    user_id_str = str(user_id)
    try:
        users_for_profile = load_users()
        _remember_user_profile(users_for_profile, user_id_str, from_obj)
        save_users(users_for_profile)
    except Exception as e:
        print(f"[profile] {e}")

    # ── lang همیشه از همین ابتدا مقداردهی می‌شه تا در هیچ شاخه‌ای
    #    UnboundLocalError نگیریم (باگ اصلی که باعث کرش تابع می‌شد) ──
    try:
        lang = _get_user_lang(user_id)
    except Exception:
        lang = "fa"
    t = _T(lang)

    # ── پنل ادمین callbacks — اول از همه چک می‌شه ──
    if _ADMIN_PANEL_LOADED and is_admin_user(user_id) and (callback_data.startswith("adm:") or callback_data.startswith("adm_sch_") or callback_data.startswith("adm_bc_") or callback_data.startswith("adm_musr_") or callback_data.startswith("adm_lang:")):
        handle_admin_callback(callback_data, callback_query_id, chat_id, user_id, message_id)
        return

    # ── گیت سراسری عضویت اجباری ──
    # نکته: joined_order از گیت مستثنی است. کاربری که هنوز عضو کانال‌های اجباری
    # نشده ممکن است از داخل کانال یک سفارش دیگر روی «عضو شدم» بزند؛ چون او خودش
    # هنوز سفارشی ثبت نکرده، اشکالی ندارد سکه‌اش را بگیرد — برای ثبت سفارش خودش
    # بعداً باید عضو کانال‌های اجباری شود (آن مسیر همچنان توسط گیت پوشش داده می‌شود).
    if callback_data not in ("accept_rules", "check_membership") and not callback_data.startswith("joined_order:") and not callback_data.startswith("opengift:") and _required_channels_gate(chat_id, user_id):
        bale_api.answer_callback_query(callback_query_id)
        return

    if callback_data == "accept_rules":
        users = load_users()
        _get_or_init_user(users, user_id_str)
        lang = users[user_id_str].get("lang", "fa")
        t = _T(lang)
        if users[user_id_str].get("rules_accepted"):
            bale_api.answer_callback_query(callback_query_id, t("toast_rules_already_accepted"))
            return
        users[user_id_str]["rules_accepted"] = True
        save_users(users)
        bale_api.answer_callback_query(callback_query_id, t("toast_rules_accepted"))
        bale_api.send_message(chat_id, t("join_prompt"),
                              reply_markup=build_keyboard_channel_join_and_check(lang))
 
    elif callback_data == "check_membership":
        users = load_users()
        _get_or_init_user(users, user_id_str)
        lang = users[user_id_str].get("lang", "fa")
        t = _T(lang)
        all_joined = all(
            is_user_in_specific_channel(ch["username"], user_id)
            for ch in _all_required_channels()
        )
        if all_joined:
            users[user_id_str]["is_verified_member"] = True
            users[user_id_str]["rules_accepted"] = True
            save_users(users)
            bale_api.answer_callback_query(callback_query_id, t("toast_membership_confirmed"))
            if is_admin_user(user_id):
                kb = build_reply_main_menu_admin(lang)
            else:
                kb = build_reply_main_menu(lang)
            bale_api.send_message(chat_id, t("welcome"), reply_markup=kb)
            _send_active_predictions_to_user(user_id, lang)
        else:
            bale_api.answer_callback_query(callback_query_id, t("toast_membership_not_complete"))
            bale_api.send_message(
                chat_id,
                t("not_in_channel"),
                reply_markup=build_keyboard_channel_join_and_check(lang)
            )
 
    elif callback_data.startswith("select_members:"):
        parts = callback_data.split(":")
        member_count = int(parts[1])
        coins_needed = float(parts[2])
        users = load_users()
        user_data = _get_or_init_user(users, user_id_str)
        user_coins = user_data.get("coins", 0)
        if user_coins < coins_needed:
            bale_api.answer_callback_query(callback_query_id, t("toast_insufficient_coins"))
            bale_api.send_message(chat_id,
                INSUFFICIENT_COINS_MESSAGE_TEMPLATE.format(needed=coins_needed, balance=user_coins),
                reply_markup=build_member_count_keyboard(user_coins, lang))
            return
        if user_data.get("state") != "waiting_for_member_count":
            bale_api.answer_callback_query(callback_query_id, t("toast_send_channel_first"))
            return
        users[user_id_str]["pending_member_count"] = member_count
        users[user_id_str]["pending_coins_needed"] = coins_needed
        users[user_id_str]["state"] = "waiting_for_order_confirm"
        save_users(users)
        bale_api.answer_callback_query(callback_query_id)
        channel_id = users[user_id_str].get("order_channel", "")
        bale_api.send_message(chat_id,
            t("order_details").format(channel_id=channel_id, member_count=member_count, coins_needed=coins_needed),
            reply_markup=build_order_confirm_keyboard(member_count, coins_needed, lang))
 
    elif callback_data.startswith("order_confirm:"):
        parts = callback_data.split(":")
        member_count = int(parts[1])
        coins_needed = float(parts[2])
        users = load_users()
        user_data = _get_or_init_user(users, user_id_str)
        if user_data.get("state") != "waiting_for_order_confirm" or user_data.get("order_confirm_handled"):
            bale_api.answer_callback_query(callback_query_id, t("toast_order_already_processed"))
            return
        users[user_id_str]["order_confirm_handled"] = True
        users[user_id_str]["state"] = "idle"
        save_users(users)
        bale_api.answer_callback_query(callback_query_id, t("toast_order_placing"))
        _place_order(chat_id, user_id, user_id_str, member_count, coins_needed)
 
    elif callback_data == "order_cancel":
        users = load_users()
        user_data = _get_or_init_user(users, user_id_str)
        if user_data.get("state") != "waiting_for_order_confirm" or user_data.get("order_confirm_handled"):
            bale_api.answer_callback_query(callback_query_id, t("toast_order_already_processed"))
            return
        users[user_id_str]["order_confirm_handled"] = True
        users[user_id_str]["state"] = "idle"
        users[user_id_str].pop("order_channel", None)
        users[user_id_str].pop("pending_member_count", None)
        users[user_id_str].pop("pending_coins_needed", None)
        save_users(users)
        bale_api.answer_callback_query(callback_query_id)
        bale_api.send_message(chat_id, t("order_cancel_back"), reply_markup=_build_menu(user_id, lang))
 
    elif callback_data == "order_pricing_inline":
        bale_api.answer_callback_query(callback_query_id)
        bale_api.send_message(chat_id, t("pricing_msg"))
 
    elif callback_data == "order_back":
        users = load_users()
        if user_id_str in users:
            users[user_id_str].pop("state", None)
            users[user_id_str].pop("order_channel", None)
            save_users(users)
        bale_api.answer_callback_query(callback_query_id)
        bale_api.send_message(chat_id, t("back_to_main_menu"), reply_markup=_build_menu(user_id, lang))
 
    elif callback_data.startswith("opengift:"):
        contest_id = int(callback_data.split(":")[1])
        contest = get_contest(contest_id)
        if not contest or contest.get("type") != "gift_envelope":
            bale_api.answer_callback_query(callback_query_id, t("ge_not_found_toast"))
            return
        claimed_by = contest.get("claimed_by", [])
        if user_id_str in claimed_by:
            bale_api.answer_callback_query(callback_query_id, t("ge_already_opened_toast"))
            return
        capacity = contest.get("capacity", 0)
        if len(claimed_by) >= capacity or contest.get("status") != "active":
            bale_api.answer_callback_query(callback_query_id, t("ge_already_opened_toast"))
            return
        coins = contest.get("coins", 0)
        users = load_users()
        _get_or_init_user(users, user_id_str)
        users[user_id_str]["coins"] = round(users[user_id_str].get("coins", 0) + coins, 2)
        save_users(users)
        claimed_by.append(user_id_str)
        contest["claimed_by"] = claimed_by
        if len(claimed_by) >= capacity:
            contest["status"] = "ended"
            contest["ended_at"] = datetime.now().isoformat()
            mid = contest.get("channel_message_id")
            if mid:
                try:
                    bale_api.delete_message(_main_channel_target(), mid)
                except Exception as e:
                    print(f"[gift_envelope_delmsg] {e}")
                contest["channel_message_id"] = None
        _save_contest(contest)
        bale_api.answer_callback_query(callback_query_id, t("ge_opened_toast").format(coins=_fmt_coins(coins)))

    elif callback_data.startswith("joined_order:"):
        order_id = int(callback_data.split(":")[1])
        check_and_penalty_left_channels(user_id)
        orders = load_orders()
        order = next((o for o in orders["orders"] if o["order_id"] == order_id), None)
        if not order:
            bale_api.answer_callback_query(callback_query_id, t("toast_order_not_found"))
            return
        if order.get("status") != "active":
            bale_api.answer_callback_query(callback_query_id, t("toast_order_not_active"))
            return
        channel_id = order["channel_id"]
        # چک فوری ادمین بودن ربات — اگر کاربر ربات را از ادمینی خارج کرده، سفارش همان لحظه لغو شود
        try:
            _adm_status = _channel_admin_status(channel_id)
            if _adm_status == "not_found":
                _force_cancel_order(order, orders, "order_cancelled_link_changed")
                bale_api.answer_callback_query(callback_query_id, t("toast_order_not_active"))
                return
            if _adm_status == "not_admin":
                _force_cancel_order(order, orders, "order_cancelled_bot_removed")
                bale_api.answer_callback_query(callback_query_id, t("toast_order_not_active"))
                return
        except Exception as e:
            print(f"[joined_order/admin_check] {e}")
        users = load_users()
        user_data = _get_or_init_user(users, user_id_str)
        if channel_id in user_data.get("joined_channels", {}):
            bale_api.answer_callback_query(callback_query_id, t("toast_already_joined"))
            return
        earned_orders = user_data.get("earned_orders", [])
        if order_id in earned_orders:
            bale_api.answer_callback_query(callback_query_id, t("toast_already_joined"))
            return
        if not is_user_in_specific_channel(channel_id, user_id):
            bale_api.answer_callback_query(callback_query_id, t("toast_not_joined_yet"))
            return
        is_joiner_vip = _is_vip(user_id_str, users)
        order_owner_vip = order.get("is_vip", False)
        coin_reward = get_referral_gift(is_vip=True) if (is_joiner_vip or order_owner_vip) else get_referral_gift(is_vip=False)
        users[user_id_str]["coins"] = round(user_data.get("coins", 0) + coin_reward, 2)
        users[user_id_str].setdefault("joined_channels", {})[channel_id] = {
            "join_time": datetime.now().isoformat(), "order_id": order_id}
        if order_id not in earned_orders:
            earned_orders.append(order_id)
        users[user_id_str]["earned_orders"] = earned_orders
        save_users(users)
 
        # ثبت در لیدربورد
        user_name = _get_user_display_name(users, user_id_str)
        lb_record_join(user_id, user_name, users[user_id_str]["coins"])
 
        order["members_joined"] = order.get("members_joined", 0) + 1
        order["coins_remaining"] = max(0, order.get("coins_remaining", 0) - 2)
        if order["members_joined"] >= order["member_count"]:
            order["status"] = "completed"
            if order.get("message_id"):
                bale_api.delete_message(_main_channel_target(), order["message_id"])
        save_orders(orders)
        coin_msg_tpl = t("coin_added_rxn_vip") if (is_joiner_vip or order_owner_vip) else t("coin_added")
        coin_msg = coin_msg_tpl.format(coins=_fmt_coins(coin_reward))
        bale_api.answer_callback_query(callback_query_id, coin_msg)
 
    elif callback_data.startswith("cancel_order:"):
        order_id = int(callback_data.split(":")[1])
        orders = load_orders()
        order = next((o for o in orders["orders"] if o["order_id"] == order_id), None)
        if not order:
            bale_api.answer_callback_query(callback_query_id, t("toast_order_not_found"))
            return
        if order.get("user_id") != user_id:
            bale_api.answer_callback_query(callback_query_id, t("toast_order_not_yours"))
            return
        if order.get("status") != "active":
            bale_api.answer_callback_query(callback_query_id, t("toast_order_not_cancellable"))
            return
        coins_remaining = order.get("coins_remaining", 0)
        penalty = round(coins_remaining * 0.2, 2)
        refund  = round(coins_remaining * 0.8, 2)
        order["status"] = "cancelled"
        save_orders(orders)
        if order.get("message_id"):
            bale_api.delete_message(_main_channel_target(), order["message_id"])
        users = load_users()
        _get_or_init_user(users, user_id_str)
        users[user_id_str]["coins"] = round(users[user_id_str].get("coins", 0) + refund, 2)
        save_users(users)
        bale_api.answer_callback_query(callback_query_id, t("toast_order_cancelled"))
        bale_api.send_message(chat_id,
            t("order_cancelled_msg").format(refund=refund, penalty=penalty),
            reply_markup=_build_menu(user_id, lang))
 
    elif callback_data.startswith("report_order:"):
        order_id = int(callback_data.split(":")[1])
        orders = load_orders()
        reports = load_reports()
        order = next((o for o in orders["orders"] if o["order_id"] == order_id), None)
        if not order:
            bale_api.answer_callback_query(callback_query_id, t("toast_order_not_found"))
            return
        already = any(r.get("reporter_user_id") == user_id and r.get("order_id") == order_id
                      for r in reports["reports"])
        if already:
            bale_api.answer_callback_query(callback_query_id, t("toast_report_already_submitted"))
            return
        bale_api.answer_callback_query(callback_query_id, t("toast_report_registered"))
        order["report_count"] += 1
        save_orders(orders)
        report = {"report_id": len(reports["reports"]) + 1, "order_id": order_id,
                  "reporter_user_id": user_id, "channel_id": order["channel_id"],
                  "status": "pending", "message_id": order.get("message_id"),
                  "order_message_chat_id": CHANNEL_USERNAME}
        reports["reports"].append(report)
        save_reports(reports)
        admin_lang = _get_user_lang(ADMIN_ID)
        at = _T(admin_lang)
        bale_api.send_message(ADMIN_ID,
            at("admin_report_msg").format(channel_id=order["channel_id"]),
            reply_markup=build_admin_report_inline_keyboard(report["report_id"]))
        try:
            bale_api.send_message(user_id, t("report_registered_msg"))
        except Exception:
            pass
 
    elif callback_data.startswith("confirm_report:"):
        report_id = int(callback_data.split(":")[1])
        reports = load_reports()
        orders = load_orders()
        report = next((r for r in reports["reports"] if r["report_id"] == report_id), None)
