GAMES_FILE = "games_data.json"
_games_lock = threading.Lock()

def load_games():
    with _games_lock:
        return db.load_json(GAMES_FILE, lambda: {"players": {}})

def save_games(data):
    with _games_lock:
        db.save_json(GAMES_FILE, data)

def _today_str():
    return datetime.now().strftime("%Y-%m-%d")

def _game_played_today(user_id_str, game_key):
    data = load_games()
    player = data["players"].get(user_id_str, {})
    return player.get(f"{game_key}_date") == _today_str()

def _mark_game_played(user_id_str, game_key, extra=None):
    data = load_games()
    if user_id_str not in data["players"]:
        data["players"][user_id_str] = {}
    data["players"][user_id_str][f"{game_key}_date"] = _today_str()
    if extra:
        for k, v in extra.items():
            data["players"][user_id_str][k] = v
    save_games(data)

def _get_player_data(user_id_str):
    data = load_games()
    return data["players"].get(user_id_str, {})

def _set_player_data(user_id_str, key, value):
    data = load_games()
    if user_id_str not in data["players"]:
        data["players"][user_id_str] = {}
    data["players"][user_id_str][key] = value
    save_games(data)

