def handle_guess_start(chat_id, user_id):
    import random
    lang = _get_user_lang(user_id)
    t = _T(lang)
    user_id_str = str(user_id)
    if _game_played_today(user_id_str, "guess"):
        bale_api.send_message(chat_id, t("guess_already"), reply_markup=build_games_menu_keyboard(lang))
        return
    secret = random.randint(1, 10)
    data = load_games()
    if user_id_str not in data["players"]:
        data["players"][user_id_str] = {}
    data["players"][user_id_str]["guess_secret"] = secret
    data["players"][user_id_str]["guess_attempts"] = 0
    data["players"][user_id_str]["guess_active"] = True
    save_games(data)
    users = load_users()
    _get_or_init_user(users, user_id_str)
    users[user_id_str]["state"] = "waiting_for_guess"
    save_users(users)
    bale_api.send_message(chat_id, t("guess_welcome"), reply_markup=build_guess_back_keyboard(lang))

def handle_guess_input(chat_id, user_id, text):
    lang = _get_user_lang(user_id)
    t = _T(lang)
    user_id_str = str(user_id)
    data = load_games()
    player = data["players"].get(user_id_str, {})
    if not player.get("guess_active"):
        return
    secret = player.get("guess_secret")
    attempts = player.get("guess_attempts", 0)
    try:
        guess = int(text.strip())
    except ValueError:
        bale_api.send_message(chat_id, t("guess_enter_num"), reply_markup=build_guess_back_keyboard(lang))
        return
    if guess > 10:
        bale_api.send_message(chat_id, t("guess_too_big"), reply_markup=build_guess_back_keyboard(lang))
        return
    if guess < 1:
        bale_api.send_message(chat_id, t("guess_too_small"), reply_markup=build_guess_back_keyboard(lang))
        return
    attempts += 1
    if guess == secret:
        # برنده
        data["players"][user_id_str]["guess_attempts"] = attempts
        data["players"][user_id_str]["guess_active"] = False
        data["players"][user_id_str]["guess_date"] = _today_str()
        save_games(data)
        users = load_users()
        _get_or_init_user(users, user_id_str)
        users[user_id_str]["coins"] = round(users[user_id_str].get("coins", 0) + 3, 2)
        users[user_id_str]["state"] = "idle"
        save_users(users)
        _guess_win = {
            "fa": f"🎉 *فوق‌العاده بود!*\n\n✅️ بله! عدد *{secret}* بود.\n\n🎁 پاداش: ۳ سکه اضافه شد.",
            "en": f"🎉 *Amazing!*\n\n✅️ Yes! The number was *{secret}*.\n\n🎁 Reward: 3 coins added.",
            "fr": f"🎉 *Incroyable!*\n\n✅️ Oui! Le nombre était *{secret}*.\n\n🎁 Récompense: 3 pièces ajoutées.",
            "ar": f"🎉 *رائع!*\n\n✅️ نعم! الرقم كان *{secret}*.\n\n🎁 المكافأة: 3 عملات أضيفت.",
        }
        bale_api.send_message(chat_id, _guess_win.get(lang, _guess_win["fa"]),
            reply_markup=build_games_menu_keyboard(lang))
        return
    # اشتباه
    data["players"][user_id_str]["guess_attempts"] = attempts
    save_games(data)
    remaining = 3 - attempts
    if remaining <= 0:
        # باخت
        data["players"][user_id_str]["guess_active"] = False
        data["players"][user_id_str]["guess_date"] = _today_str()
        save_games(data)
        users = load_users()
        _get_or_init_user(users, user_id_str)
        users[user_id_str]["state"] = "idle"
        save_users(users)
        _guess_loss = {
            "fa": f"*💀 باخت! فرصت‌ها به پایان رسید.*\n\nعدد مورد نظر آرکا *{secret}* بود.\n\n❌ در این دور سکه‌ای دریافت نکردید.",
            "en": f"*💀 Lost! Chances over.*\n\nThe number was *{secret}*.\n\n❌ No coins this round.",
            "fr": f"*💀 Perdu! Plus de chances.*\n\nLe nombre était *{secret}*.\n\n❌ Pas de pièces ce tour.",
            "ar": f"*💀 خسرت! انتهت الفرص.*\n\nكان الرقم *{secret}*.\n\n❌ لا عملات هذه الجولة.",
        }
        bale_api.send_message(chat_id, _guess_loss.get(lang, _guess_loss["fa"]),
            reply_markup=build_games_menu_keyboard(lang))
        return
    if attempts == 1:
        _wrong1 = {
            "fa": f"*❌ نادرست بود!*\n\nنه، عدد مورد نظر *{guess}* نیست.\n\n⚠️ ۱ فرصت از ۳ از دست رفت. هنوز شانس دارید!",
            "en": f"*❌ Wrong!*\n\nNo, the number is not *{guess}*.\n\n⚠️ 1 of 3 chances used. You still have chances!",
            "fr": f"*❌ Faux!*\n\nNon, le nombre n'est pas *{guess}*.\n\n⚠️ 1 sur 3 utilisé. Vous avez encore des chances!",
            "ar": f"*❌ خطأ!*\n\nلا، الرقم ليس *{guess}*.\n\n⚠️ فرصة 1 من 3. لا تزال لديك فرص!",
        }
        msg = _wrong1.get(lang, _wrong1["fa"])
    else:
        _wrong2 = {
            "fa": f"*❌ باز هم اشتباه بود!*\n\nنه، عدد مورد نظر *{guess}* نیست.\n\n🔥 این آخرین شانس شماست!",
            "en": f"*❌ Wrong again!*\n\nNo, the number is not *{guess}*.\n\n🔥 This is your last chance!",
            "fr": f"*❌ Encore faux!*\n\nNon, le nombre n'est pas *{guess}*.\n\n🔥 C'est votre dernière chance!",
            "ar": f"*❌ خطأ مرة أخرى!*\n\nلا، الرقم ليس *{guess}*.\n\n🔥 هذه فرصتك الأخيرة!",
        }
        msg = _wrong2.get(lang, _wrong2["fa"])
    bale_api.send_message(chat_id, msg, reply_markup=build_guess_back_keyboard(lang))
